    }
}

// MARK: - CaptainLogger.swift

/// Queue-confined storage: encoding and disk access never run on the game/UI thread.
final class CaptainLogger: @unchecked Sendable {
    enum Sobriety: String, Codable, CaseIterable, Sendable {
        case sober, tipsy, drunken
        var title: String {
            switch self {
            case .sober: "Трезв как стекло"
            case .tipsy: "Слегка навеселе"
            case .drunken: "Совсем пьян"
            }
        }
    }

    struct Entry: Codable, Identifiable, Sendable {
        let id: UUID
        let date: Date
        let expedition: UUID
        let event: String
        let sobriety: Sobriety
        let message: String
        let details: [String: String]
    }

    static let shared = CaptainLogger(url: URL.applicationSupportDirectory
        .appendingPathComponent("CaptainLogger/watch-journal.json"))
    private let queue = DispatchQueue(label: "CaptainLogger.storage", qos: .utility)
    private let url: URL
    private var entries: [Entry] = []
    private var loaded = false
    private var dirty = false
    private var scheduled = false
    private var storageError: String?
    private var loadFailed = false
    private let capacity: Int

    init(url: URL, capacity: Int = 2_000) {
        self.url = url
        self.capacity = max(1, capacity)
    }

    func record(_ event: String, message: String, expedition: UUID,
                sobriety: Sobriety, details: [String: String] = [:]) {
        let prose: String
        switch sobriety {
        case .sober: prose = message
        case .tipsy: prose = "Так, записываю… \(message)"
        case .drunken:
            prose = "\(message) Эх, нелегка служба на подлодке: потолок низкий, море со всех сторон, а до дома ещё сколько вахт… Даже чай в кружке мечтает сойти на берег."
        }
        let entry = Entry(id: UUID(), date: Date(), expedition: expedition, event: event,
                          sobriety: sobriety, message: prose,
                          details: sobriety == .sober ? details : details.filter { ["hull", "energy", "reason"].contains($0.key) })
        queue.async {
            self.load()
            self.entries.append(entry)
            self.entries = Array(self.entries.suffix(self.capacity))
            self.dirty = true
            guard !self.scheduled else { return }
            self.scheduled = true
            self.queue.asyncAfter(deadline: .now() + 1) {
                self.scheduled = false
                self.persist()
            }
        }
    }

    /// Flushes queued events before returning newest-first records. Errors remain visible to readers.
    func read() async -> (entries: [Entry], error: String?) {
        await withCheckedContinuation { continuation in
            queue.async {
                self.load()
                self.persist()
                continuation.resume(returning: (self.entries.reversed(), self.storageError))
            }
        }
    }

    func flush() {
        queue.async { self.load(); self.persist() }
    }

    private func load() {
        guard !loaded else { return }
        loaded = true
        guard FileManager.default.fileExists(atPath: url.path) else { return }
        do {
            entries = Array(try JSONDecoder().decode([Entry].self, from: Data(contentsOf: url)).suffix(capacity))
        } catch {
            loadFailed = true // Never overwrite an unreadable historical journal.
            storageError = "Не удалось прочитать журнал: \(error.localizedDescription)"
        }
    }

    private func persist() {
        guard dirty, !loadFailed else { return }
        do {
            try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
            try JSONEncoder().encode(entries).write(to: url, options: .atomic)
            dirty = false
            storageError = nil
        } catch {
            storageError = "Не удалось сохранить журнал: \(error.localizedDescription)"
        }
    }
}

struct CaptainJournalView: View {
    let logger: CaptainLogger
    @AppStorage("podlodkaDive.captainSobriety") private var sobriety = CaptainLogger.Sobriety.sober
    @Environment(\.dismiss) private var dismiss
    @State private var entries: [CaptainLogger.Entry] = []
    @State private var storageError: String?
    @State private var query = ""
    @State private var visibleLimit = 50

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 20) {
                Text("Вахтенный журнал").font(.title).accessibilityAddTraits(.isHeader)
                Button("Готово") { dismiss() }
                Text("Степень трезвости").font(.body)
                ForEach(CaptainLogger.Sobriety.allCases, id: \.self) { value in
                    Button {
                        sobriety = value
                    } label: {
                        Label(value.title, systemImage: sobriety == value ? "checkmark.circle.fill" : "circle")
                    }
                    .accessibilityAddTraits(sobriety == value ? .isSelected : [])
                }
                Text("Трезвый капитан фиксирует все приборы. Навеселе — только корпус и заряд. Пьяный ещё и рассуждает о службе.")
                TextField("Поиск событий", text: $query).textFieldStyle(.roundedBorder)
                Button("Обновить") { Task { await reload() } }
                if let storageError { Text(storageError) }
                Text("Последние записи · до 2000").font(.body)
                if entries.isEmpty { Text("Вахтенный журнал пока пуст.") }
                ForEach(entries.filter { query.isEmpty || $0.message.localizedCaseInsensitiveContains(query) || $0.event.localizedCaseInsensitiveContains(query) }.prefix(visibleLimit)) { entry in
                    VStack(alignment: .leading, spacing: 6) {
                        Text(entry.date, format: .dateTime.day().month().hour().minute().second())
                        Text(entry.message)
                        Text("\(entry.sobriety.title) · \(entry.event) · рейс \(entry.expedition.uuidString.prefix(8))")
                        ForEach(entry.details.keys.sorted(), id: \.self) { key in
                            Text("\(key): \(entry.details[key] ?? "")")
                        }
                    }
                    .fixedSize(horizontal: false, vertical: true)
                    .accessibilityElement(children: .combine)
                    Divider()
                }
                if visibleLimit < entries.count { Button("Ещё записи") { visibleLimit += 50 }.font(.body) }
            }
            .font(.body)
            .padding(24)
            .buttonStyle(.bordered)
            .controlSize(.large)
        }
        .foregroundStyle(.black)
        .background(.white)
        .tint(.black)
        .preferredColorScheme(.light)
        .task { await reload() }
        .refreshable { await reload() }
        .onChange(of: query) { _, _ in visibleLimit = 50 }
    }

    private func reload() async {
        let result = await logger.read()
        entries = result.entries
        storageError = result.error
    }
}

// MARK: - BlackBox.swift

enum BlackBoxLevel: String, Codable, CaseIterable, Sendable { case debug, info, warning, error }
enum BlackBoxCategory: String, Codable, CaseIterable, Sendable { case state, control, flow, event, hazard, resource, captain, system }
struct BlackBoxEntry: Codable, Identifiable, Sendable, Equatable {
    var id = UUID()
    let runID: UUID
    var seq: Int
    let t: TimeInterval
    let wallTime: Date
    var schemaVersion = 1
    let level: BlackBoxLevel
    let category: BlackBoxCategory
    let message: String
    let attrs: [String: String]
    var expendable: Bool { level == .debug || message == "snapshot" }
}
@Model final class BlackBoxRow {
    @Attribute(.unique) var id: UUID
    var runID: UUID
    var seq: Int
    var wallTime: Date
    var payload: Data
    init(_ entry: BlackBoxEntry) throws {
        id = entry.id; runID = entry.runID; seq = entry.seq; wallTime = entry.wallTime
        payload = try JSONEncoder().encode(entry)
    }
}
@ModelActor actor BlackBoxStore {
    func write(_ entries: [BlackBoxEntry]) throws {
        do {
            for entry in entries { modelContext.insert(try BlackBoxRow(entry)) }
            if entries.contains(where: { $0.message == "run.start" || $0.message == "run.end" }) {
                let retained = try retainedIDs()
                let rows = try modelContext.fetch(FetchDescriptor<BlackBoxRow>())
                for row in rows where !retained.contains(row.runID) { modelContext.delete(row) }
            }
            try modelContext.save()
        } catch { modelContext.rollback(); throw error }
    }
    func page(runID: UUID?, after: Int, limit: Int) throws -> [BlackBoxEntry] {
        let predicate: Predicate<BlackBoxRow>
        if let runID { predicate = #Predicate { $0.runID == runID && $0.seq > after } }
        else { predicate = #Predicate { $0.seq > after } }
        var request = FetchDescriptor(predicate: predicate, sortBy: [SortDescriptor(\BlackBoxRow.seq)])
        request.fetchLimit = min(max(limit, 1), 512)
        return try modelContext.fetch(request).map { try JSONDecoder().decode(BlackBoxEntry.self, from: $0.payload) }
    }
    func runs() throws -> [UUID] {
        let rows = try modelContext.fetch(FetchDescriptor<BlackBoxRow>(sortBy: [SortDescriptor(\BlackBoxRow.wallTime, order: .reverse)]))
        var seen = Set<UUID>()
        return try rows.compactMap { row in
            let entry = try JSONDecoder().decode(BlackBoxEntry.self, from: row.payload)
            return entry.message == "run.start" && seen.insert(row.runID).inserted ? row.runID : nil
        }
    }
    private func retainedIDs() throws -> Set<UUID> {
        var retained = Set(try runs().prefix(10))
        let rows = try modelContext.fetch(FetchDescriptor<BlackBoxRow>())
        for row in rows where retained.contains(row.runID) {
            let entry = try JSONDecoder().decode(BlackBoxEntry.self, from: row.payload)
            if let session = entry.attrs["sessionID"].flatMap(UUID.init(uuidString:)) { retained.insert(session) }
        }
        return retained
    }
    func recoverAndPrune() throws -> Int {
        let ids = try runs()
        let rows = try modelContext.fetch(FetchDescriptor<BlackBoxRow>())
        var sequence = rows.map(\.seq).max() ?? 0
        for id in ids.prefix(10) {
            let entries = try rows.filter { $0.runID == id }.map { try JSONDecoder().decode(BlackBoxEntry.self, from: $0.payload) }
            if entries.contains(where: { $0.message == "run.start" }) && !entries.contains(where: { $0.message == "run.end" }) {
                sequence += 1
                let entry = BlackBoxEntry(runID: id, seq: sequence, t: entries.map(\.t).max() ?? 0, wallTime: Date(), level: .warning, category: .system, message: "run.end", attrs: ["outcome": "interrupted"])
                modelContext.insert(try BlackBoxRow(entry))
            }
        }
        let retained = try retainedIDs()
        for row in rows where !retained.contains(row.runID) { modelContext.delete(row) }
        try modelContext.save()
        return sequence
    }
}
struct BlackBoxReader: Sendable {
    let store: BlackBoxStore
    func runs() async throws -> [UUID] { try await store.runs() }
    func page(runID: UUID? = nil, after: Int = 0, limit: Int = 100) async throws -> [BlackBoxEntry] {
        try await store.page(runID: runID, after: after, limit: limit)
    }
    func all(runID: UUID? = nil) async throws -> [BlackBoxEntry] {
        var result: [BlackBoxEntry] = [], cursor = 0
        while true {
            let batch = try await page(runID: runID, after: cursor, limit: 512)
            guard let last = batch.last else { return result }
            result += batch; cursor = last.seq
        }
    }
}
actor BlackBox {
    static let shared = BlackBox()
    private let output = Logger(subsystem: "io.podlodka.dive", category: "BlackBox")
    private var store: BlackBoxStore?
    private var buffer: [BlackBoxEntry] = []
    private var sequence = 0
    private var timer: Task<Void, Never>?
    private var writing = false
    private var waiters: [CheckedContinuation<Void, Never>] = []
    private var recovered = false
    private var recoveryTask: Task<Int, Error>?
    private(set) var storageError: String?
    private let storeFactory: @Sendable () throws -> BlackBoxStore
    private let now: @Sendable () -> Date
    private let sleep: @Sendable () async throws -> Void
    init(store: BlackBoxStore? = nil, now: @escaping @Sendable () -> Date = { Date() },
         sleep: @escaping @Sendable () async throws -> Void = { try await Task.sleep(for: .seconds(3)) },
         storeFactory: @escaping @Sendable () throws -> BlackBoxStore = {
             BlackBoxStore(modelContainer: try ModelContainer(for: BlackBoxRow.self))
         }) {
        self.store = store; self.now = now; self.sleep = sleep; self.storeFactory = storeFactory
    }
    func reader() async -> BlackBoxReader? {
        await recover()
        return recovered ? store.map { BlackBoxReader(store: $0) } : nil
    }
    private func prepare() {
        if store == nil {
            do { store = try storeFactory() }
            catch {
                storageError = error.localizedDescription
                output.error("Database unavailable: \(error.localizedDescription)")
            }
        }
        guard timer == nil else { return }
        let sleep = self.sleep
        timer = Task { [weak self] in
            while !Task.isCancelled {
                do { try await sleep() } catch { return }
                guard self != nil else { return }
                await self?.flush()
            }
        }
    }
    func recover() async {
        guard !recovered else { return }
        prepare()
        guard let store else { return }
        if recoveryTask == nil {
            recoveryTask = Task { try await store.recoverAndPrune() }
        }
        do {
            let restored = try await recoveryTask?.value ?? 0
            guard !recovered else { return }
            // Events buffered before the disk became available follow the persisted sequence.
            for index in buffer.indices { buffer[index].seq += restored }
            sequence += restored
            recovered = true
            storageError = nil
        } catch {
            storageError = error.localizedDescription
            recoveryTask = nil
            output.error("Recovery failed: \(error.localizedDescription)")
        }
    }
    func log(_ level: BlackBoxLevel = .info, _ category: BlackBoxCategory, _ message: String,
             attrs: [String: String] = [:], runID: UUID, t: TimeInterval) async {
        await recover(); sequence += 1
        if level == .error { output.error("\(message, privacy: .public) \(attrs.description)") }
        if buffer.count >= 512 {
            if let index = buffer.firstIndex(where: \.expendable) { buffer.remove(at: index) }
            else if level == .debug || message == "snapshot" { return }
            // Critical events are retained even when storage is unavailable. The cap is soft for them.
        }
        buffer.append(BlackBoxEntry(runID: runID, seq: sequence, t: t, wallTime: now(), level: level, category: category, message: message, attrs: attrs))
        if buffer.count >= 64 { await flush() }
    }
    func flush() async {
        await recover()
        guard recovered else { return }
        if writing {
            await withCheckedContinuation { waiters.append($0) }
            await flush(); return
        }
        guard let store, !buffer.isEmpty else { return }
        writing = true
        let batch = buffer
        do {
            try await store.write(batch)
            let ids = Set(batch.map(\.id)); buffer.removeAll { ids.contains($0.id) }
            storageError = nil
        } catch {
            storageError = error.localizedDescription
            output.error("Flush failed: \(error.localizedDescription)")
        }
        writing = false
        let pending = waiters; waiters = []; pending.forEach { $0.resume() }
    }
}

/// Serial task chain preserves synchronous Combine delivery order, without disk work in simulation.
@MainActor final class BlackBoxRecorder: ObservableObject {
    private let logger: BlackBox
    private var subscription: AnyCancellable?
    private var tail: Task<Void, Never>?
    private var runID = UUID()
    private var started = ProcessInfo.processInfo.systemUptime
    private var active = false
    private var ticks = 0
    private weak var engine: GameEngine?
    private var screen = "launch"
    init(engine: GameEngine, logger: BlackBox = .shared) {
        self.logger = logger
        self.engine = engine
        tail = Task { await logger.recover() }
        record(.system, "app.launch")
        if let error = engine.garageLoadError { record(.system, "garage.load.failed", level: .error, attrs: ["reason": error]) }
        subscription = engine.events.sink { [weak self, weak engine] event in
            guard let self, let engine else { return }
            switch event {
            case .runStarted(let id):
                let sessionID = runID
                runID = id; active = true; ticks = 0
                record(.state, "run.start", attrs: ["sessionID": sessionID.uuidString, "style": engine.selectedStyle.rawValue,
                    "night": String(UserDefaults.standard.bool(forKey: "podlodkaDive.nightExpedition")), "best": String(engine.bestScore)].merging(engine.missionMetadata) { _, new in new })
                snapshot(engine.situationSummary, boundary: true)
            case .runEnded(let outcome):
                guard active else { return }
                snapshot(engine.situationSummary, boundary: true)
                record(.state, "run.end", attrs: ["outcome": outcome, "score": String(engine.score), "best": String(engine.bestScore), "reason": outcome == ExpeditionOutcome.gameOver.rawValue ? String(describing: engine.failureReason) : outcome])
                active = false; flush()
                runID = UUID(); started = ProcessInfo.processInfo.systemUptime
            case .stateChanged(let state):
                record(.state, String(describing: state)); flow(String(describing: state))
            case .situation(let summary): ticks += 1; if ticks % 4 == 0 { snapshot(summary) }
            case .danger(let text): record(.hazard, text, level: .warning); snapshot(engine.situationSummary, boundary: true)
            case .speak(let text):
                record(.event, text)
            case .energyLow: record(.resource, "energyLow", level: .warning)
            case .objectiveChanged(let value): record(.event, "blackBox", attrs: ["collected": String(value)])
            case .success(let score): record(.event, "success", attrs: ["score": String(score)])
            case .record(let score): record(.event, "record", attrs: ["score": String(score)])
            case .diagnostic(let level, let category, let message, let attrs): record(category, message, level: level, attrs: attrs)
            }
        }
    }
    func timestamp() -> (UUID, Double) { (runID, active ? (engine?.runElapsed ?? 0) : ProcessInfo.processInfo.systemUptime - started) }
    func record(_ category: BlackBoxCategory, _ message: String, level: BlackBoxLevel = .info, attrs: [String: String] = [:], timestamp: (UUID, Double)? = nil) {
        let logger = self.logger
        let captured = timestamp ?? self.timestamp()
        let previous = tail, id = captured.0, t = captured.1
        tail = Task { await previous?.value; await logger.log(level, category, message, attrs: attrs, runID: id, t: t) }
    }
    func flow(_ next: String) { guard next != screen else { return }; record(.flow, "screen", attrs: ["from": screen, "to": next]); screen = next }
    func flush() { let logger = self.logger; let previous = tail; tail = Task { await previous?.value; await logger.flush() } }
    func background() {
        let token = UIApplication.shared.beginBackgroundTask(withName: "BlackBox flush")
        record(.system, "app.background")
        Task { await drain(); if token != .invalid { UIApplication.shared.endBackgroundTask(token) } }
    }
    func drain() async { await tail?.value; await logger.flush() }
    private func snapshot(_ s: SituationSummary, boundary: Bool = false) {
        record(.state, boundary ? "snapshot.boundary" : "snapshot", attrs: ["zone": s.zone, "x": String(Double(s.position.x)), "y": String(Double(s.position.y)), "energy": String(Double(s.energy)), "hull": String(s.hull), "speed": String(s.speed), "target": s.targetName ?? "Чёрный ящик"].merging(engine?.missionMetadata ?? [:]) { _, new in new })
    }
}

// MARK: - BlackBoxView.swift

// Serializes the audio callback with shutdown; the Speech request never crosses alone.
private final class SpeechAudioSink: @unchecked Sendable {
    private let lock = NSLock()
    private let request: SFSpeechAudioBufferRecognitionRequest
    private var ended = false
    init(request: SFSpeechAudioBufferRecognitionRequest) { self.request = request }
    func append(_ buffer: AVAudioPCMBuffer) {
        lock.lock()
        defer { lock.unlock() }
        guard !ended else { return }
        request.append(buffer)
    }
    func finish() {
        lock.lock()
        defer { lock.unlock() }
        guard !ended else { return }
        ended = true
        request.endAudio()
    }
}

@MainActor protocol VoiceNoteTranscriber: AnyObject {
    func start(update: @escaping @MainActor (String) -> Void, failure: @escaping @MainActor (String) -> Void) async throws
    func stop()
}
@MainActor final class DeviceVoiceNoteTranscriber: VoiceNoteTranscriber {
    private let audio = AVAudioEngine()
    private var audioSink: SpeechAudioSink?
    private var task: SFSpeechRecognitionTask?
    private var installed = false
    func start(update: @escaping @MainActor (String) -> Void, failure: @escaping @MainActor (String) -> Void) async throws {
        let status = await withCheckedContinuation { continuation in
            Self.requestSpeechAuthorization(continuation: continuation)
        }
        let microphone = await AVAudioApplication.requestRecordPermission()
        guard status == .authorized, microphone else { throw NoteError.permission }
        guard let recognizer = SFSpeechRecognizer(locale: .current), recognizer.isAvailable,
              recognizer.supportsOnDeviceRecognition else { throw NoteError.unavailable }
        let session = AVAudioSession.sharedInstance()
        try session.setCategory(.playAndRecord, mode: .measurement, options: [.mixWithOthers, .defaultToSpeaker]); try session.setActive(true)
        let request = SFSpeechAudioBufferRecognitionRequest()
        request.requiresOnDeviceRecognition = true; request.shouldReportPartialResults = true
        let sink = SpeechAudioSink(request: request)
        audioSink = sink
        let input = audio.inputNode
        let format = input.outputFormat(forBus: 0)
        guard format.channelCount > 0, format.sampleRate > 0 else { stop(); throw NoteError.unavailable }
        input.installTap(onBus: 0, bufferSize: 1024, format: format) { @Sendable buffer, _ in sink.append(buffer) }
        installed = true
        task = recognizer.recognitionTask(with: request) { @Sendable result, error in
            if let error { Task { @MainActor in failure(error.localizedDescription) } }
            if let text = result?.bestTranscription.formattedString { Task { @MainActor in update(text) } }
        }
        do { audio.prepare(); try audio.start() } catch { stop(); throw error }
    }
    static func requestSpeechAuthorization(
        continuation: CheckedContinuation<SFSpeechRecognizerAuthorizationStatus, Never>,
        request: (@escaping @Sendable (SFSpeechRecognizerAuthorizationStatus) -> Void) -> Void = {
            SFSpeechRecognizer.requestAuthorization($0)
        }
    ) {
        request { @Sendable status in continuation.resume(returning: status) }
    }

    func stop() {
        audio.stop()
        if installed { audio.inputNode.removeTap(onBus: 0); installed = false }
        audioSink?.finish(); task?.cancel(); task = nil; audioSink = nil
        try? AVAudioSession.sharedInstance().setActive(false, options: .notifyOthersOnDeactivation)
    }
    enum NoteError: LocalizedError {
        case permission, unavailable
        var errorDescription: String? { String(localized: "journal.voice.unavailable") }
    }
}
@MainActor final class CaptainNote: ObservableObject {
    @Published var recording = false
    @Published var busy = false
    @Published var text = ""
    @Published var error: String?
    private var generation = 0
    private var timestamp: (UUID, Double)?
    private let transcriber: any VoiceNoteTranscriber
    init(transcriber: any VoiceNoteTranscriber = DeviceVoiceNoteTranscriber()) { self.transcriber = transcriber }
    func toggle(recorder: BlackBoxRecorder) async {
        guard !busy else { return }
        if recording { finish(recorder: recorder); return }
        busy = true; text = ""; error = nil
        generation += 1; let attempt = generation
        timestamp = recorder.timestamp()
        do {
            try await transcriber.start(update: { [weak self] text in
                guard let self, self.generation == attempt else { return }
                self.text = text
            }, failure: { [weak self] reason in
                guard let self, self.generation == attempt else { return }
                self.error = reason; self.finish(recorder: recorder)
                recorder.record(.captain, "voice.failed", level: .error, attrs: ["reason": reason])
            })
            guard generation == attempt else { transcriber.stop(); busy = false; return }
            recording = true
        }
        catch {
            transcriber.stop()
            if generation == attempt {
                self.error = error.localizedDescription
                recorder.record(.captain, "voice.denied", level: .error, attrs: ["reason": error.localizedDescription])
            }
        }
        busy = false
    }
    func finish(recorder: BlackBoxRecorder) {
        generation += 1
        guard recording else { return }
        transcriber.stop(); recording = false
        if !text.isEmpty { recorder.record(.captain, text, timestamp: timestamp); recorder.flush() }
    }
}

struct ReplaySample: Equatable {
    let zone: String
    let t: Double
    let x: Double
    let y: Double
    let energy: Double
    let hull: Double
    let speed: Double
    init?(_ entry: BlackBoxEntry) {
        guard entry.message.hasPrefix("snapshot"), let x = Double(entry.attrs["x"] ?? ""), let y = Double(entry.attrs["y"] ?? "") else { return nil }
        zone = entry.attrs["zone"] ?? "ocean"
        t = entry.t; self.x = x; self.y = y
        energy = Double(entry.attrs["energy"] ?? "") ?? 0
        hull = Double(entry.attrs["hull"] ?? "") ?? 0
        speed = Double(entry.attrs["speed"] ?? "") ?? 0
    }
    init(t: Double, x: Double, y: Double, energy: Double, hull: Double, speed: Double, zone: String = "ocean") {
        self.zone = zone
        self.t = t; self.x = x; self.y = y; self.energy = energy; self.hull = hull; self.speed = speed
    }
    static func interpolate(_ samples: [ReplaySample], at t: Double) -> ReplaySample? {
        guard let first = samples.first else { return nil }
        let a = samples.last(where: { $0.t <= t }) ?? first
        let b = samples.first(where: { $0.t > t }) ?? a
        let fraction = b.t > a.t && a.zone == b.zone ? max(0, min(1, (t - a.t) / (b.t - a.t))) : 0
        func mix(_ x: Double, _ y: Double) -> Double { x + (y - x) * fraction }
        return ReplaySample(t: t, x: mix(a.x, b.x), y: mix(a.y, b.y), energy: mix(a.energy, b.energy), hull: a.hull, speed: mix(a.speed, b.speed), zone: a.zone)
    }
}
struct BlackBoxJournal: View {
    @Environment(\.dismiss) private var dismiss
    @State private var runs: [UUID] = []
    @State private var reader: BlackBoxReader?
    @State private var error = ""
    var body: some View {
        NavigationStack {
            List {
                Button("journal.close") { dismiss() }.font(.body).frame(minHeight: 44)
                if !error.isEmpty { Text(error) }
                NavigationLink("journal.flow") { JournalTimeline(reader: reader, runID: nil) }.accessibilityIdentifier("blackBoxFlow")
                ForEach(runs, id: \.self) { id in
                    NavigationLink(id.uuidString.prefix(8)) { JournalTimeline(reader: reader, runID: id) }.accessibilityIdentifier("journalRun")
                }
                if runs.isEmpty { Text("journal.empty") }
            }
            .font(.body)
            .navigationTitle("journal.title")
            .task {
                await BlackBox.shared.flush()
                reader = await BlackBox.shared.reader()
                if let failure = await BlackBox.shared.storageError { error = failure }
                do { runs = try await reader?.runs() ?? []; if reader == nil { error = String(localized: "journal.storage.error") } }
                catch { self.error = error.localizedDescription }
            }
        }
    }
}
struct JournalTimeline: View {
    let reader: BlackBoxReader?
    let runID: UUID?
    @State private var entries: [BlackBoxEntry] = []
    @State private var category = "all"
    @State private var time = 0.0
    @State private var playing = false
    @State private var error = ""
    @State private var exportURL: URL?
    @State private var spokenEvent: UUID?
    @State private var visibleLimit = 100
    private var samples: [ReplaySample] { entries.compactMap(ReplaySample.init).sorted { $0.t < $1.t } }
    private var duration: Double { max(entries.map(\.t).max() ?? 0, 0.001) }
    private var filtered: [BlackBoxEntry] { entries.filter { category == "all" || $0.category.rawValue == category } }
    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 16) {
                if !error.isEmpty { Text(error) }
                if runID != nil {
                    Section("journal.replay") {
                        ExpeditionMap(samples: samples, entries: entries, time: time).frame(height: 260)
                        if let sample = ReplaySample.interpolate(samples, at: time) {
                            Text("E \(Int(sample.energy))% · ♥ \(Int(sample.hull)) · \(Int(sample.speed)) m/s")
                        }
                        Text("\(time, specifier: "%.1f") / \(duration, specifier: "%.1f") с")
                            .accessibilityIdentifier("replayTime")
                        Slider(value: $time, in: 0...duration).accessibilityIdentifier("replaySeek").accessibilityLabel(Text("journal.seek"))
                            .accessibilityValue(Text("\(Int(time)) s"))
                        Button { playing.toggle() } label: {
                            Text(playing ? "journal.pause" : "journal.play")
                                .font(.body).frame(minHeight: 44).contentShape(Rectangle())
                        }
                    }
                }
                Section("journal.flow") { FlowGraph(entries: entries).frame(minHeight: 220) }
                Picker("journal.filter", selection: $category) {
                    Text("journal.all").tag("all")
                    ForEach(BlackBoxCategory.allCases, id: \.rawValue) { Text(LocalizedStringKey("journal.category." + $0.rawValue)).tag($0.rawValue) }
                }
                if let exportURL { ShareLink(item: exportURL) { Label("journal.export", systemImage: "square.and.arrow.up").frame(minHeight: 44).contentShape(Rectangle()) } }
                ShareLink(item: entries.map { "\(Int($0.t))s [\($0.category.rawValue)] \($0.message)" }.joined(separator: "\n")) { Text("journal.summary").frame(minHeight: 44).contentShape(Rectangle()) }
                ForEach(filtered.prefix(visibleLimit)) { entry in
                    Button { time = entry.t; playing = false; UIAccessibility.post(notification: .announcement, argument: entry.message) } label: {
                        VStack(alignment: .leading) {
                            Text("\(Int(entry.t))s · \(entry.category.rawValue)").font(.body)
                            Text(entry.category == .captain ? "“\(entry.message)”" : entry.message)
                        }.frame(maxWidth: .infinity, minHeight: 44, alignment: .leading).contentShape(Rectangle())
                    }.frame(maxWidth: .infinity, minHeight: 44, alignment: .leading)
                    .padding(8)
                    .background(abs(entry.t - time) < 0.5 ? Color.accentColor.opacity(0.15) : Color.clear)
                }
                if visibleLimit < filtered.count { Button { visibleLimit += 100 } label: { Text("Ещё события").frame(minHeight: 44).contentShape(Rectangle()) } }
            }
            .font(.body).foregroundStyle(.primary).buttonStyle(.plain).padding(20)
            .onChange(of: category) { _, _ in visibleLimit = 100 }
            .onChange(of: time) { _, value in
                if let entry = filtered.last(where: { $0.t <= value }) {
                    if abs(entry.t - value) < 0.11 && entry.category != .state && spokenEvent != entry.id {
                        spokenEvent = entry.id
                        UIAccessibility.post(notification: .announcement, argument: entry.message)
                    }
                }
            }
        }
        .font(.body)
            .navigationTitle("journal.title")
        .task {
            do {
                entries = try await reader?.all(runID: runID) ?? []
                let exported = entries, exportID = runID
                exportURL = try await Task.detached(priority: .utility) {
                    let encoder = JSONEncoder(); encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
                    let data = try encoder.encode(exported)
                    let url = FileManager.default.temporaryDirectory.appendingPathComponent("blackbox-\(exportID?.uuidString ?? "all").json")
                    try data.write(to: url, options: .atomic); return url
                }.value
            } catch { self.error = error.localizedDescription }
        }
        .task(id: playing) {
            guard playing else { return }
            while !Task.isCancelled {
                do { try await Task.sleep(for: .milliseconds(100)) } catch { return }
                time = min(duration, time + 0.1)
                if time >= duration { playing = false; return }
            }
        }
    }
}
struct ReplayMap: View {
    let samples: [ReplaySample]
    let entries: [BlackBoxEntry]
    let time: Double
    var body: some View {
        Canvas { context, size in
            let level = OceanLevel.expedition
            let zone = ReplaySample.interpolate(samples, at: time)?.zone ?? "ocean"
            let bounds = zone == "bossCave" ? GameEngine.caveSize : level.size
            let scale = min(size.width / bounds.width, size.height / bounds.height)
            func point(_ x: Double, _ y: Double) -> CGPoint { CGPoint(x: x * scale, y: y * scale) }
            for rock in zone == "ocean" ? level.rocks : [] {
                var path = Path(); path.addLines(rock.vertices.map { point($0.x, $0.y) }); path.closeSubpath()
                context.fill(path, with: .color(.teal.opacity(0.3)))
            }
            var path = Path()
            var previousZone = ""
            for sample in samples {
                if sample.zone == zone {
                    if previousZone == zone { path.addLine(to: point(sample.x, sample.y)) }
                    else { path.move(to: point(sample.x, sample.y)) }
                }
                previousZone = sample.zone
            }
            context.stroke(path, with: .color(.teal), lineWidth: 2)
            for entry in entries where entry.category == .captain || entry.category == .hazard || entry.message == "blackBox" {
                if let sample = ReplaySample.interpolate(samples, at: entry.t), sample.zone == zone {
                    let p = point(sample.x, sample.y)
                    context.fill(Path(ellipseIn: CGRect(x: p.x - 3, y: p.y - 3, width: 6, height: 6)), with: .color(.orange))
                    if entry.category == .captain && abs(entry.t - time) < 3 {
                        context.draw(Text("“\(entry.message.prefix(40))”").font(.body), at: CGPoint(x: p.x, y: p.y - 16))
                    }
                }
            }
            if let sample = ReplaySample.interpolate(samples, at: time) {
                let p = point(sample.x, sample.y)
                context.fill(Path(ellipseIn: CGRect(x: p.x - 6, y: p.y - 6, width: 12, height: 12)), with: .color(.white))
            }
        }.accessibilityLabel(Text("journal.replay"))
    }
}
struct FlowGraph: View {
    let entries: [BlackBoxEntry]
    private var edges: [String: Int] {
        entries.filter { $0.category == .flow }.reduce(into: [:]) { result, entry in
            result["\(entry.attrs["from"] ?? "?") → \(entry.attrs["to"] ?? "?")", default: 0] += 1
        }
    }
    var body: some View {
        VStack(alignment: .leading) {
            FlowGraphRows(edges: edges.keys.sorted().compactMap { key in
                let parts = key.components(separatedBy: " → ")
                guard parts.count == 2 else { return nil }
                return FlowEdge(from: parts[0], to: parts[1], count: edges[key] ?? 0)
            })
        }
    }
}

/// Live and historical presentations of the expedition map; replay never mutates an engine.
struct ExpeditionMap: View {
    var engine: GameEngine? = nil
    var samples: [ReplaySample] = []
    var entries: [BlackBoxEntry] = []
    var time: Double = 0
    var body: some View {
        if let engine { LiveExpeditionMap(engine: engine) }
        else { ReplayMap(samples: samples, entries: entries, time: time) }
    }
}

