        if state == .paused, var saved = pausedSnapshot {
            saved.missionRun = missionRun
            return saved
        }
        return ExpeditionSnapshot(id: expeditionID,
            level: level,
            position: position,
            velocity: velocity,
            steering: steering,
            camera: camera,
            facing: facing,
            energy: energy,
            hull: hull,
            hasShield: hasShield,
            hasBlackBox: hasBlackBox,
            samples: samples,
            score: score,
            bestAtStart: bestAtStart,
            runElapsed: runElapsed,
            distance: distance,
            pickups: pickups,
            mines: mines,
            revealedPickups: revealedPickups,
            trail: trail,
            notice: notice,
            failureReason: failureReason,
            zone: zone,
            portal: portal,
            portalRevealed: portalRevealed,
            bossStrike: bossStrike,
