// MARK: - ExpeditionRecovery.swift

struct ReturnRoute: Equatable {
    let id: UUID
    var url: URL { URL(string: "podlodkadive://expedition/\(id.uuidString)")! }
    init(id: UUID) { self.id = id }
    init?(url: URL) {
        guard url.scheme?.lowercased() == "podlodkadive", url.host == "expedition",
              url.pathComponents.count == 2, url.query == nil, url.fragment == nil,
              let id = UUID(uuidString: url.lastPathComponent) else { return nil }
        self.id = id
    }
}

struct ReturnEvent: Codable, Identifiable {
    let id: UUID
    let expedition: UUID?
    let date: Date
    let kind: String
    let title: String
    let text: String
    var sourceEventID: UUID? = nil
    var read = false
    var isNotification: Bool { kind.hasPrefix("push") }
}

@MainActor
protocol ReminderClient {
    func authorize() async throws -> Bool
    func pending() async -> [UNNotificationRequest]
    func replace(_ requests: [UNNotificationRequest]) async throws
    func cancel()
}

final class LocalReminderClient: ReminderClient {
    static let identifiers = ["expedition.return.1", "expedition.return.7"]
    let center = UNUserNotificationCenter.current()
    func authorize() async throws -> Bool {
        try await center.requestAuthorization(options: [.alert, .sound, .badge])
    }
    func pending() async -> [UNNotificationRequest] {
        await center.pendingNotificationRequests()
    }
    func replace(_ requests: [UNNotificationRequest]) async throws {
        cancel()
        do { for request in requests { try await center.add(request) } }
        catch { cancel(); throw error }
    }
    func cancel() {
        center.removePendingNotificationRequests(withIdentifiers: Self.identifiers)
        center.removeDeliveredNotifications(withIdentifiers: Self.identifiers)
    }
}

struct ReminderPlan {
    static func requests(id: UUID, eventID: UUID, now: Date, calendar: Calendar) -> [UNNotificationRequest] {
        [1, 7].compactMap { days in
            guard let date = calendar.date(byAdding: .day, value: days, to: now) else { return nil }
            let content = UNMutableNotificationContent()
            content.title = "Экспедиция ждёт капитана"
            content.body = "Продолжите сохранённое погружение. Игра откроется на паузе."
            content.sound = .default
            content.userInfo = ["url": ReturnRoute(id: id).url.absoluteString, "eventID": eventID.uuidString]
            // Floating calendar components preserve local wall time after time-zone changes.
            let components = calendar.dateComponents([.year, .month, .day, .hour, .minute, .second], from: date)
            return UNNotificationRequest(identifier: "expedition.return.\(days)", content: content,
                trigger: UNCalendarNotificationTrigger(dateMatching: components, repeats: false))
        }
    }
}

/// Installed before SwiftUI creates its root. Pending routes survive cold-start ordering.
@MainActor
final class ReturnInbox: ObservableObject {
    static let shared = ReturnInbox()
    @Published var pending: URL?
    var opened: ((URL, UUID?) -> Void)?
    func receive(_ url: URL, eventID: UUID? = nil) {
        if let opened { opened(url, eventID) } else { pending = url; pendingEventID = eventID }
    }
    private var pendingEventID: UUID?
    func connect(_ handler: @escaping (URL, UUID?) -> Void) {
        opened = handler
        if let pending { handler(pending, pendingEventID); self.pending = nil; pendingEventID = nil }
    }
}

final class ReturnNotificationDelegate: NSObject, UIApplicationDelegate, UNUserNotificationCenterDelegate {
    func application(_ application: UIApplication, didFinishLaunchingWithOptions options: [UIApplication.LaunchOptionsKey: Any]? = nil) -> Bool {
        UNUserNotificationCenter.current().delegate = self
        return true
    }
    nonisolated func userNotificationCenter(_ center: UNUserNotificationCenter, didReceive response: UNNotificationResponse,
                                withCompletionHandler completionHandler: @escaping () -> Void) {
        let info = response.notification.request.content.userInfo
        if let raw = info["url"] as? String, let url = URL(string: raw) {
            let eventID = (info["eventID"] as? String).flatMap(UUID.init(uuidString:))
            Task { @MainActor in ReturnInbox.shared.receive(url, eventID: eventID) }
        }
        completionHandler()
    }
    nonisolated func userNotificationCenter(_ center: UNUserNotificationCenter, willPresent notification: UNNotification,
                                withCompletionHandler completionHandler: @escaping (UNNotificationPresentationOptions) -> Void) {
        completionHandler([.banner, .list, .sound])
    }
}

@MainActor
final class ExpeditionRecovery: ObservableObject {
    @Published private(set) var savedID: UUID?
    @Published private(set) var history: [ReturnEvent] = []
    @Published var message: String?
    @Published var replacement: ReturnRoute?
    private weak var engine: GameEngine?
    private let directory: URL
    private let client: any ReminderClient
    private let now: () -> Date
    private let calendar: () -> Calendar
    private var generation = UUID()
    private var operations: Task<Void, Never>?
    private var resumedID: UUID?
    private var exited = false
    private var remindersPending = false
    private var saveURL: URL { directory.appendingPathComponent("expedition.json") }
    private var eventsURL: URL { directory.appendingPathComponent("events.json") }

    init(engine: GameEngine, directory: URL? = nil, client: any ReminderClient = LocalReminderClient(),
         now: @escaping () -> Date = Date.init, calendar: @escaping () -> Calendar = { .current }) {
        self.engine = engine
        self.directory = directory ?? FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0].appendingPathComponent("ExpeditionReturn")
        self.client = client; self.now = now; self.calendar = calendar
        do {
            try FileManager.default.createDirectory(at: self.directory, withIntermediateDirectories: true)
            if FileManager.default.fileExists(atPath: eventsURL.path) {
                history = try JSONDecoder().decode([ReturnEvent].self, from: Data(contentsOf: eventsURL))
            }
        } catch { message = "Не удалось прочитать историю событий." }
        remindersPending = history.first { ["pushScheduled", "pushCancelled", "pushError"].contains($0.kind) }?.kind == "pushScheduled"
        if FileManager.default.fileExists(atPath: saveURL.path) {
            do { savedID = try load().id }
            catch { failure(); deleteSave() }
        } else { client.cancel() }
    }

    func load() throws -> ExpeditionSnapshot {
        let data = try Data(contentsOf: saveURL)
        guard data.count <= 5_000_000 else { throw RecoveryError.corrupt }
        // Bound all numeric payloads before any engine conversion to Int or geometry math.
        func validNumbers(_ value: Any) -> Bool {
            if let number = value as? NSNumber { return number.doubleValue.isFinite && abs(number.doubleValue) <= 1_000_000_000 }
            if let values = value as? [Any] { return values.allSatisfy(validNumbers) }
            if let values = value as? [String: Any] { return values.values.allSatisfy(validNumbers) }
            return true
        }
        guard validNumbers(try JSONSerialization.jsonObject(with: data)) else { throw RecoveryError.corrupt }
        struct Header: Decodable { let version: Int }
        guard try JSONDecoder().decode(Header.self, from: data).version == 1 else { throw RecoveryError.version }
        let save = try JSONDecoder().decode(ExpeditionSnapshot.self, from: data)
        guard !history.contains(where: { $0.expedition == save.id && ["completed", "gameOver", "saveDeleted"].contains($0.kind) }) else { throw RecoveryError.corrupt }
        guard save.hull > 0, save.hull <= 3, save.energy > 0, save.energy <= 100,
              save.level.size.width > 0, save.level.size.height > 0,
              save.samples >= 0, save.samples <= save.level.pickups.count, save.runElapsed >= 0,
              Set(save.pickups.map(\.id)).count == save.pickups.count,
              Set(save.mines.map(\.id)).count == save.mines.count else { throw RecoveryError.corrupt }
        return save
    }
    enum RecoveryError: Error { case version, corrupt }

    @discardableResult
    func save(exiting: Bool) -> Bool {
        guard let engine, engine.state == .playing || engine.state == .paused else { return true }
        if exiting && exited { return true }
        do {
            let snapshot = engine.snapshot()
            try JSONEncoder().encode(snapshot).write(to: saveURL, options: .atomic)
            savedID = snapshot.id
            record("save", title: "Экспедиция сохранена", text: "Положение, груз и состояние океана сохранены.")
            if exiting { exited = true; schedule(id: snapshot.id) }
            return true
        } catch { message = "Не удалось сохранить экспедицию. Повторите попытку."; return false }
    }

    func record(_ kind: String, title: String, text: String, id: UUID = UUID(), expedition: UUID? = nil, sourceEventID: UUID? = nil) {
        guard !history.contains(where: { $0.id == id }) else { return }
        let run = expedition ?? engine?.expeditionId.flatMap(UUID.init(uuidString:)) ?? savedID
        history.insert(ReturnEvent(id: id, expedition: run, date: now(), kind: kind, title: title, text: text, sourceEventID: sourceEventID), at: 0)
        engine?.captainLogger.record(kind, message: title, expedition: run ?? id, sobriety: .sober,
                                     details: ["domainEventID": id.uuidString])
        persistHistory()
    }
    private func persistHistory() {
        do { try JSONEncoder().encode(history).write(to: eventsURL, options: .atomic) }
        catch { message = "Не удалось сохранить историю событий." }
    }
    func markRead(_ id: UUID) {
        guard let index = history.firstIndex(where: { $0.id == id }) else { return }
        history[index].read.toggle(); persistHistory()
    }
    enum Filter: String, CaseIterable { case all = "Все", unread = "Непрочитанные", notifications = "Уведомления" }
    func events(_ filter: Filter) -> [ReturnEvent] {
        history.filter { filter == .all || (filter == .unread ? !$0.read : $0.isNotification) }
    }
    func canOpen(_ event: ReturnEvent) -> Bool { event.expedition != nil && event.expedition == savedID }

    struct ReminderPreview: Identifiable {
        let id: String
        let title: String
        let body: String
        let date: Date
        let url: URL
    }

    /// Read the system queue, not the historical scheduling event. Never asks for permission.
    func reminderPreviews() async -> [ReminderPreview] {
        await settle()
        let requests = await client.pending()
        guard let savedID else { return [] }
        return requests.compactMap { request in
            guard LocalReminderClient.identifiers.contains(request.identifier),
                  let raw = request.content.userInfo["url"] as? String,
                  let url = URL(string: raw), ReturnRoute(url: url)?.id == savedID,
                  let trigger = request.trigger as? UNCalendarNotificationTrigger,
                  let date = trigger.nextTriggerDate() else { return nil }
            return ReminderPreview(id: request.identifier, title: request.content.title,
                                   body: request.content.body, date: date, url: url)
        }.sorted { $0.date < $1.date }
    }

    private func schedule(id: UUID) {
        generation = UUID()
        remindersPending = true
        let token = generation, date = now(), cal = calendar(), eventID = UUID()
        let prior = operations
        operations = Task { [weak self] in
            await prior?.value
            guard let self, self.generation == token else { return }
            do {
                self.client.cancel()
                guard try await self.client.authorize() else {
                    if self.generation == token { self.remindersPending = false }
                    return
                }
                guard self.generation == token else { return }
                try await self.client.replace(ReminderPlan.requests(id: id, eventID: eventID, now: date, calendar: cal))
                guard self.generation == token else { self.client.cancel(); return }
                self.record("pushScheduled", title: "Напоминания включены", text: "Завтра и через неделю в это же местное время.", id: eventID, expedition: id)
            } catch {
                guard self.generation == token else { return }
                self.remindersPending = false
                self.record("pushError", title: "Напоминания недоступны", text: "Сохранение можно открыть кнопкой «Продолжить».", expedition: id)
            }
        }
    }
    func cancelReminders() {
        generation = UUID(); client.cancel(); exited = false
        let prior = operations
        operations = Task { [client] in await prior?.value; client.cancel() }
        if remindersPending, let id = savedID {
            record("pushCancelled", title: "Напоминания отменены", text: "Оставшиеся напоминания этой экспедиции отменены.", expedition: id)
        }
        remindersPending = false
    }
    func settle() async { await operations?.value }
    func deleteSave() {
        cancelReminders()
        if let savedID { record("saveDeleted", title: "Сохранение удалено", text: "История экспедиции остаётся доступной.", expedition: savedID) }
        do {
            if FileManager.default.fileExists(atPath: saveURL.path) { try FileManager.default.removeItem(at: saveURL) }
            savedID = nil; resumedID = nil
        } catch { message = "Не удалось удалить сохранение." }
    }
    private func failure() {
        message = "Сохранение отсутствует, повреждено или несовместимо. Начните новую экспедицию на главном экране."
        record("restoreError", title: "Не удалось продолжить", text: message!)
    }
    func open(_ url: URL, pushEventID: UUID? = nil, confirmed: Bool = false) {
        guard let route = ReturnRoute(url: url), let engine else { failure(); return }
        if let pushEventID {
            if let index = history.firstIndex(where: { $0.id == pushEventID }) { history[index].read = true; persistHistory() }
            if !history.contains(where: { $0.kind == "pushOpened" && $0.sourceEventID == pushEventID }) {
                record("pushOpened", title: "Напоминание открыто", text: "Открываем сохранённую экспедицию.", expedition: route.id, sourceEventID: pushEventID)
            }
        }
        do {
            let snapshot = try load()
            guard snapshot.id == route.id else { failure(); return }
            let active = engine.state == .playing || engine.state == .paused
            if active && engine.expeditionId == route.id.uuidString {
                if resumedID != route.id { engine.pause(); cancelReminders(); resumedID = route.id }
                return
            }
            if active && !confirmed { replacement = route; return }
            engine.restore(snapshot); resumedID = route.id; exited = false
            cancelReminders()
            record("restore", title: "Экспедиция восстановлена", text: "Игра на паузе. Продолжите, когда будете готовы.")
        } catch {
            failure()
            if savedID == route.id { deleteSave() }
            if engine.state != .playing && engine.state != .paused { engine.returnToMenu() }
        }
    }
}

struct ReturnEventsView: View {
    @ObservedObject var recovery: ExpeditionRecovery
    let open: (URL) -> Void
    @Environment(\.dismiss) private var dismiss
    @State private var filter: ExpeditionRecovery.Filter = .all
    @AccessibilityFocusState private var titleFocused: Bool
    @Environment(\.scenePhase) private var scenePhase
    @State private var previews: [ExpeditionRecovery.ReminderPreview] = []
    @State private var loadingPreviews = true
    var body: some View {
        NavigationStack {
            List {
                Button("Готово") { dismiss() }.font(.body).frame(minHeight: 44).accessibilityIdentifier("closeEvents").accessibilityFocused($titleFocused)
                Section("Предпросмотр напоминаний") {
                    if loadingPreviews {
                        ProgressView("Проверяем напоминания")
                    } else if previews.isEmpty {
                        Text("Нет запланированных напоминаний для сохранённой экспедиции.")
                    } else {
                        ForEach(previews) { preview in
                            VStack(alignment: .leading, spacing: 8) {
                                Text(preview.title).font(.headline)
                                Text(preview.body)
                                Text(preview.date, format: .dateTime.day().month().year().hour().minute())
                                Button("Проверить переход в экспедицию") {
                                    dismiss(); open(preview.url)
                                }
                                .accessibilityHint("Открывает сохранение на паузе и отменяет оставшиеся напоминания")
                            }.padding(.vertical, 4)
                        }
                        Text("Время местное. Показ уведомления зависит от настроек уведомлений и режима фокусирования iOS.")
                    }
                    Button {
                        Task { await refreshPreviews() }
                    } label: {
                        Text("Обновить напоминания").fixedSize(horizontal: false, vertical: true)
                    }.font(.body).frame(minHeight: 44).disabled(loadingPreviews)
                }
                Picker(selection: $filter) {
                    ForEach(ExpeditionRecovery.Filter.allCases, id: \.self) { Text($0.rawValue).tag($0) }
                } label: {
                    Text("Фильтр событий").fixedSize(horizontal: false, vertical: true)
                }.font(.body).frame(minHeight: 44).accessibilityIdentifier("eventFilter")
                if recovery.events(filter).isEmpty { Text("Нет событий").font(.body).fixedSize(horizontal: false, vertical: true).frame(minHeight: 44).accessibilityIdentifier("emptyEvents") }
                ForEach(recovery.events(filter)) { event in
                    VStack(alignment: .leading, spacing: 8) {
                        Text(event.title).font(.headline)
                        Text(event.date, format: .dateTime.day().month().year().hour().minute())
                        Text(event.text)
                        Button(event.read ? "Прочитано · отметить непрочитанным" : "Не прочитано · отметить прочитанным") { recovery.markRead(event.id) }
                            .accessibilityHint("Меняет статус этого события")
                        if recovery.canOpen(event), let id = event.expedition {
                            Button("Открыть экспедицию") { dismiss(); open(ReturnRoute(id: id).url) }
                                .accessibilityHint("Открывает сохранение на паузе")
                        }
                    }.padding(.vertical, 4)
                }
            }
            .font(.body)
            .navigationTitle("События")
            .onAppear { titleFocused = true }
            .task(id: scenePhase) {
                if scenePhase == .active { await refreshPreviews() }
            }
        }
    }

    @MainActor private func refreshPreviews() async {
        loadingPreviews = true
        previews = await recovery.reminderPreviews()
        loadingPreviews = false
    }
}

// MARK: - GameCanvas.swift

enum OceanPalette {
    static let ink = Color(red: 0.025, green: 0.10, blue: 0.15)
    static let teal = Color(red: 0.38, green: 0.89, blue: 0.80)
    static let gold = Color(red: 1, green: 0.77, blue: 0.33)
    static let muted = Color(red: 0.56, green: 0.72, blue: 0.75)
    static let white = Color.white
    static let danger = Color(red: 1, green: 0.43, blue: 0.35)
    static let blue = Color(red: 0.4, green: 0.72, blue: 1)
    static let portal = Color(red: 0.75, green: 0.43, blue: 1)
}

struct GameCanvas: View {
    @ObservedObject var engine: GameEngine
    let nightExpedition: Bool
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    private var time: Double { reduceMotion ? 0 : engine.elapsed }

    var body: some View {
        Canvas { context, actualSize in
            let scale = actualSize.width / engine.viewport.width
            context.scaleBy(x: scale, y: scale)
            let size = engine.viewport
            drawWater(in: &context, size: size)
            if engine.state == .ready {
                drawWelcome(in: &context, size: size)
            } else {
                context.drawLayer { world in
                    world.translateBy(x: size.width / 2 - engine.camera.x, y: size.height / 2 - engine.camera.y)
                    if engine.zone == .bossCave { drawBossCave(in: &world) }
                    else { drawWorld(in: &world) }
                }
                drawLowVisibility(in: &context, size: size)
            }
            drawSubmarine(in: &context, size: size)
            if engine.state == .playing, engine.noticeRemaining <= 0, let leak = engine.journalLeak {
                let age = engine.runElapsed - leak.startedAt
                let boat = engine.screenPoint(engine.position)
                let drift = reduceMotion ? 0 : age * 9
                let width = min(260.0, size.width - 24)
                let x = min(size.width - width / 2 - 12, max(width / 2 + 12, boat.x + leak.side * 24))
                let y = min(size.height - 220, max(210, boat.y + 75 - drift))
                context.drawLayer { bubble in
                    bubble.opacity = reduceMotion ? 1 : min(1, max(0, (3.5 - age) / 0.7))
                    let rect = CGRect(x: x - width / 2, y: y - 26, width: width, height: 52)
                    bubble.fill(Path(roundedRect: rect, cornerRadius: 16), with: .color(OceanPalette.ink.opacity(0.94)))
                    bubble.stroke(Path(roundedRect: rect, cornerRadius: 16), with: .color(OceanPalette.teal.opacity(0.65)), lineWidth: 1)
                    bubble.draw(Text(leak.phrase).font(.system(size: 13, weight: .medium)).foregroundColor(OceanPalette.teal),
                                in: rect.insetBy(dx: 10, dy: 6))
                }
            }
            if engine.sonarRemaining > 0 && engine.state != .ready { drawSonar(in: &context) }
        }
        .background(OceanPalette.ink)
        .accessibilityHidden(true)
    }

    private var visible: CGRect {
        CGRect(x: engine.camera.x - engine.viewport.width / 2 - 120,
               y: engine.camera.y - engine.viewport.height / 2 - 120,
               width: engine.viewport.width + 240, height: engine.viewport.height + 240)
    }

    private func drawWater(in context: inout GraphicsContext, size: CGSize) {
        let depth = engine.state == .ready ? 0.2 : min(1, engine.camera.y / engine.level.size.height)
        context.fill(Path(CGRect(origin: .zero, size: size)), with: .linearGradient(
            Gradient(colors: [Color(red: 0.055 - depth * 0.025, green: 0.27 - depth * 0.12, blue: 0.32 - depth * 0.08),
                              OceanPalette.ink, Color(red: 0.025, green: 0.14, blue: 0.21)]),
            startPoint: .zero, endPoint: CGPoint(x: size.width, y: size.height)))
        for index in 0..<5 {
            let x = CGFloat(index) * 100 - 80 + CGFloat(sin(time * 0.18)) * 12
            var ray = Path()
            ray.move(to: CGPoint(x: x, y: 0))
            ray.addLine(to: CGPoint(x: x + 32, y: 0))
            ray.addLine(to: CGPoint(x: x - 90, y: size.height))
            ray.addLine(to: CGPoint(x: x - 180, y: size.height))
            ray.closeSubpath()
            context.fill(ray, with: .linearGradient(Gradient(colors: [OceanPalette.teal.opacity(0.045 * (1 - depth)), .clear]),
                startPoint: .zero, endPoint: CGPoint(x: 0, y: size.height)))
        }
        for index in 0..<45 {
            let parallax: CGFloat = reduceMotion || engine.state == .ready ? 0 : 0.18
            let rawX = CGFloat((index * 97) % 419) - engine.camera.x * parallax
            let rawY = CGFloat((index * 173) % 937) - engine.camera.y * parallax - CGFloat(time) * 3
            let x = (rawX.truncatingRemainder(dividingBy: size.width) + size.width).truncatingRemainder(dividingBy: size.width)
            let y = (rawY.truncatingRemainder(dividingBy: size.height) + size.height).truncatingRemainder(dividingBy: size.height)
            context.fill(Path(ellipseIn: CGRect(x: x, y: y, width: 2, height: 2)), with: .color(OceanPalette.teal.opacity(0.22)))
        }
        for index in 0..<5 {
            let y = CGFloat(index) * 160 + 160
            var tick = Path()
            tick.move(to: CGPoint(x: 12, y: y))
            tick.addLine(to: CGPoint(x: 21, y: y))
            context.stroke(tick, with: .color(OceanPalette.teal.opacity(0.12)), lineWidth: 1)
        }
    }

    private func drawWelcome(in context: inout GraphicsContext, size: CGSize) {
        let center = CGPoint(x: size.width / 2, y: size.height * 0.43)
        for radius: CGFloat in [76, 108, 140] {
            context.stroke(Path(ellipseIn: CGRect(x: center.x - radius, y: center.y - radius, width: radius * 2, height: radius * 2)),
                           with: .color(OceanPalette.teal.opacity(radius == 76 ? 0.14 : 0.06)),
                           style: StrokeStyle(lineWidth: 0.8, dash: radius == 108 ? [2, 7] : []))
        }
        for layer in 0..<3 {
            var ridge = Path()
            ridge.move(to: CGPoint(x: 0, y: size.height))
            for i in 0...16 {
                let x = CGFloat(i) * size.width / 16
                ridge.addLine(to: CGPoint(x: x, y: size.height - CGFloat(60 + layer * 40) - sin(x * 0.022 + CGFloat(layer)) * 24))
            }
            ridge.addLine(to: CGPoint(x: size.width, y: size.height))
            ridge.closeSubpath()
            context.fill(ridge, with: .color(OceanPalette.teal.opacity(0.025)))
        }
    }

    private func drawWorld(in context: inout GraphicsContext) {
        let size = engine.level.size
        let surface = CGRect(x: 0, y: 0, width: size.width, height: 100)
        context.fill(Path(surface), with: .color(OceanPalette.teal.opacity(0.09)))
        var line = Path()
        line.move(to: CGPoint(x: 0, y: 100))
        line.addLine(to: CGPoint(x: size.width, y: 100))
        context.stroke(line, with: .color(OceanPalette.teal.opacity(0.3)), lineWidth: 2)
        context.fill(Path(CGRect(x: 0, y: size.height - 25, width: size.width, height: 25)), with: .color(OceanPalette.ink))
        for zone in engine.level.currents where visible.intersects(zone.bounds) { drawCurrent(zone, in: &context) }
        for rock in engine.level.rocks where visible.intersects(rock.bounds) { drawRock(rock, in: &context) }
        if visible.insetBy(dx: -80, dy: -80).contains(engine.level.base) { drawBase(in: &context) }
        if engine.mission == .currentStation || engine.mission == .silentSignal {
            for landmark in engine.missionLandmarks where visible.insetBy(dx: -100, dy: -100).contains(landmark.position) {
                drawMissionLandmark(landmark, in: &context)
            }
        } else if visible.insetBy(dx: -120, dy: -120).contains(engine.level.wreck) {
            drawWreck(in: &context)
        }
        for pickup in engine.pickups where !pickup.collected && visible.contains(pickup.position) { drawPickup(pickup, in: &context) }
        for mine in engine.mines where visible.contains(mine.position) { drawMine(mine, in: &context) }
        if let portal = engine.portal, visible.insetBy(dx: -60, dy: -60).contains(portal.position) {
            drawPortal(portal, in: &context)
        }
        // Small schools belong to the world, making camera movement easy to read.
        for group in 0..<15 {
            let origin = CGPoint(x: CGFloat((group * 347 + 430) % 1450), y: CGFloat(group * 173 + 310))
            guard visible.contains(origin) else { continue }
            for i in 0..<5 {
                let x = origin.x + CGFloat(i * 12) + CGFloat(sin(time * 0.4)) * 14
                let y = origin.y + CGFloat((i * 17) % 29)
                context.fill(Path(ellipseIn: CGRect(x: x, y: y, width: 8, height: 3)), with: .color(OceanPalette.teal.opacity(0.2)))
            }
        }
    }

    private func drawPortal(_ portal: OceanPortal, in context: inout GraphicsContext) {
        let p = portal.position
        let pulse = reduceMotion ? 0 : CGFloat(sin(time * 2.8)) * 5
        for index in 0..<3 {
            let radius = 25 + CGFloat(index) * 12 + pulse
            context.stroke(Path(ellipseIn: CGRect(x: p.x - radius, y: p.y - radius, width: radius * 2, height: radius * 2)),
                           with: .color(OceanPalette.portal.opacity(0.75 - Double(index) * 0.18)),
                           style: StrokeStyle(lineWidth: 3 - CGFloat(index) * 0.6, dash: index == 2 ? [5, 6] : []))
        }
        context.fill(Path(ellipseIn: CGRect(x: p.x - 20, y: p.y - 20, width: 40, height: 40)),
                     with: .radialGradient(Gradient(colors: [OceanPalette.white.opacity(0.8), OceanPalette.portal.opacity(0.35), .clear]),
                                          center: p, startRadius: 1, endRadius: 22))
        if engine.portalRevealed || hypot(engine.position.x - p.x, engine.position.y - p.y) < 200 {
            drawText("ПОРТАЛ · ПЕЩЕРА", at: CGPoint(x: p.x, y: p.y + 58), color: OceanPalette.portal, in: &context)
        }
    }

    private func drawBossCave(in context: inout GraphicsContext) {
        let size = GameEngine.caveSize
        context.fill(Path(CGRect(origin: .zero, size: size)), with: .linearGradient(
            Gradient(colors: [Color(red: 0.16, green: 0.05, blue: 0.20), OceanPalette.ink, Color(red: 0.04, green: 0.02, blue: 0.09)]),
            startPoint: .zero, endPoint: CGPoint(x: size.width, y: size.height)))
        let wallColor = OceanPalette.portal.opacity(0.18)
        for side in [CGFloat(0), size.width - 52] {
            var wall = Path()
            wall.move(to: CGPoint(x: side == 0 ? 0 : size.width, y: 0))
            for index in 0...10 {
                let y = CGFloat(index) * size.height / 10
                wall.addLine(to: CGPoint(x: side + (side == 0 ? 38 : 14) + CGFloat((index * 17) % 28), y: y))
            }
            wall.addLine(to: CGPoint(x: side == 0 ? 0 : size.width, y: size.height))
            wall.closeSubpath()
            context.fill(wall, with: .color(wallColor))
        }
        drawOctopus(in: &context)
        if let strike = engine.bossStrike {
            let radius: CGFloat = 112
            let rect = CGRect(x: strike.position.x - radius, y: strike.position.y - radius, width: radius * 2, height: radius * 2)
            switch strike.phase {
            case .warning:
                let urgency = 1 - strike.timer / 1.45
                context.fill(Path(ellipseIn: rect), with: .color(OceanPalette.danger.opacity(0.08 + urgency * 0.13)))
                context.stroke(Path(ellipseIn: rect), with: .color(OceanPalette.danger),
                               style: StrokeStyle(lineWidth: 3, dash: [7, 5]))
                drawText("УДАР!", at: CGPoint(x: strike.position.x, y: strike.position.y - radius - 14), color: OceanPalette.danger, in: &context)
            case .impact:
                context.fill(Path(ellipseIn: rect), with: .color(OceanPalette.danger.opacity(0.28)))
                var tentacle = Path()
                tentacle.move(to: CGPoint(x: size.width / 2, y: 165))
                tentacle.addQuadCurve(to: strike.position, control: CGPoint(x: strike.position.x + 110, y: strike.position.y - 170))
                context.stroke(tentacle, with: .color(OceanPalette.portal), style: StrokeStyle(lineWidth: 27, lineCap: .round))
                context.stroke(tentacle, with: .color(OceanPalette.white.opacity(0.24)), style: StrokeStyle(lineWidth: 5, lineCap: .round))
            }
        }
    }

    private func drawOctopus(in context: inout GraphicsContext) {
        let center = CGPoint(x: GameEngine.caveSize.width / 2, y: 135)
        let sway = reduceMotion ? 0 : CGFloat(sin(time * 1.4)) * 9
        context.fill(Path(ellipseIn: CGRect(x: center.x - 78, y: center.y - 66, width: 156, height: 132)),
                     with: .radialGradient(Gradient(colors: [OceanPalette.portal, Color(red: 0.31, green: 0.08, blue: 0.34)]),
                                          center: CGPoint(x: center.x - 20, y: center.y - 18), startRadius: 5, endRadius: 105))
        for index in 0..<6 {
            let start = CGPoint(x: center.x - 60 + CGFloat(index) * 24, y: center.y + 43)
            var tentacle = Path()
            tentacle.move(to: start)
            tentacle.addQuadCurve(to: CGPoint(x: start.x - 45 + CGFloat(index) * 17 + sway, y: 315 + CGFloat(index % 2) * 35),
                                  control: CGPoint(x: start.x + (index.isMultiple(of: 2) ? -50 : 50), y: 235))
            context.stroke(tentacle, with: .color(OceanPalette.portal.opacity(0.8)), style: StrokeStyle(lineWidth: 18, lineCap: .round))
        }
        for x in [center.x - 28, center.x + 28] {
            context.fill(Path(ellipseIn: CGRect(x: x - 11, y: center.y - 17, width: 22, height: 29)), with: .color(OceanPalette.gold))
            context.fill(Path(ellipseIn: CGRect(x: x - 4, y: center.y - 8, width: 8, height: 14)), with: .color(OceanPalette.ink))
        }
        drawText("ГИГАНТСКИЙ СПРУТ", at: CGPoint(x: center.x, y: 78), color: OceanPalette.portal, in: &context)
    }

    private func drawRock(_ rock: OceanRock, in context: inout GraphicsContext) {
        var path = Path()
        path.addLines(rock.vertices)
        path.closeSubpath()
        let bounds = rock.bounds
        context.fill(path, with: .linearGradient(Gradient(colors: [
            Color(red: 0.075, green: 0.28, blue: 0.30), Color(red: 0.055, green: 0.19, blue: 0.23),
            Color(red: 0.025, green: 0.12, blue: 0.18)]),
            startPoint: CGPoint(x: bounds.minX, y: bounds.minY), endPoint: CGPoint(x: bounds.maxX, y: bounds.maxY)))
        context.stroke(path, with: .color(OceanPalette.teal.opacity(0.38)), lineWidth: 1.4)
        context.drawLayer { layer in
            layer.clip(to: path)
            for i in 0..<12 {
                let y = bounds.minY + CGFloat(i) * 52
                var seam = Path()
                seam.move(to: CGPoint(x: bounds.minX - 10, y: y + 40))
                seam.addLine(to: CGPoint(x: bounds.midX - 30, y: y))
                seam.addLine(to: CGPoint(x: bounds.maxX + 10, y: y + 60))
                layer.stroke(seam, with: .color(OceanPalette.ink.opacity(0.35)), lineWidth: 3)
                let x = bounds.minX + CGFloat((i * 37 + rock.id * 43) % max(1, Int(bounds.width)))
                layer.fill(Path(ellipseIn: CGRect(x: x, y: y + 13, width: 4, height: 4)), with: .color(OceanPalette.teal.opacity(0.3)))
            }
        }
        for (index, vertex) in rock.vertices.enumerated() where index.isMultiple(of: 2) {
            let p = CGPoint(x: vertex.x * 0.92 + bounds.midX * 0.08, y: vertex.y * 0.92 + bounds.midY * 0.08)
            drawCoral(at: p, height: 20 + CGFloat(index) * 2, direction: p.y < bounds.midY ? 1 : -1,
                      color: index.isMultiple(of: 4) ? OceanPalette.teal : OceanPalette.danger, in: &context)
        }
    }

    private func drawCurrent(_ zone: OceanCurrent, in context: inout GraphicsContext) {
        let rect = zone.bounds
        context.fill(Path(roundedRect: rect, cornerRadius: 45), with: .color(OceanPalette.blue.opacity(0.045)))
        let vertical = abs(zone.velocity.dy) > abs(zone.velocity.dx)
        let direction: CGFloat = (vertical ? zone.velocity.dy : zone.velocity.dx) > 0 ? 1 : -1
        context.drawLayer { layer in
            layer.clip(to: Path(rect))
            for i in 0..<28 {
                let travel = CGFloat(time) * 25 * direction
                let x = vertical ? rect.minX + CGFloat((i * 41) % max(1, Int(rect.width)))
                    : rect.minX + (CGFloat(i * 43) + travel).truncatingRemainder(dividingBy: rect.width)
                let y = vertical ? rect.minY + (CGFloat(i * 53) + travel).truncatingRemainder(dividingBy: rect.height)
                    : rect.minY + CGFloat((i * 31) % max(1, Int(rect.height)))
                var streak = Path()
                streak.move(to: CGPoint(x: x, y: y))
                streak.addLine(to: CGPoint(x: x + (vertical ? 0 : 18 * direction), y: y + (vertical ? 18 * direction : 0)))
                layer.stroke(streak, with: .color(OceanPalette.blue.opacity(0.2)), style: StrokeStyle(lineWidth: 1, lineCap: .round))
                var arrow = Path()
                if vertical {
                    arrow.move(to: CGPoint(x: x - 3, y: y + 12 * direction))
                    arrow.addLine(to: CGPoint(x: x, y: y + 18 * direction))
                    arrow.addLine(to: CGPoint(x: x + 3, y: y + 12 * direction))
                } else {
                    arrow.move(to: CGPoint(x: x + 12 * direction, y: y - 3))
                    arrow.addLine(to: CGPoint(x: x + 18 * direction, y: y))
                    arrow.addLine(to: CGPoint(x: x + 12 * direction, y: y + 3))
                }
                layer.stroke(arrow, with: .color(OceanPalette.blue.opacity(0.25)), lineWidth: 1)
            }
        }
    }

    private func drawBase(in context: inout GraphicsContext) {
        let p = engine.level.base
        let readyToDock = engine.returningToBase
        context.stroke(Path(ellipseIn: CGRect(x: p.x - 68, y: p.y - 68, width: 136, height: 136)),
                       with: .color(OceanPalette.teal.opacity(readyToDock ? 0.7 : 0.22)),
                       style: StrokeStyle(lineWidth: 1.5, dash: [4, 7]))
        var cable = Path()
        cable.move(to: CGPoint(x: p.x, y: 100))
        cable.addLine(to: CGPoint(x: p.x, y: p.y - 55))
        context.stroke(cable, with: .color(OceanPalette.muted.opacity(0.45)), lineWidth: 2)
        let dock = Path(roundedRect: CGRect(x: p.x - 54, y: p.y - 62, width: 108, height: 34), cornerRadius: 9)
        context.fill(dock, with: .color(Color(red: 0.12, green: 0.31, blue: 0.33)))
        context.stroke(dock, with: .color(OceanPalette.teal.opacity(0.6)), lineWidth: 1.2)
        for i in 0..<5 {
            context.fill(Path(roundedRect: CGRect(x: p.x - 41 + CGFloat(i) * 18, y: p.y - 53, width: 10, height: 7), cornerRadius: 2),
                         with: .color(OceanPalette.teal.opacity(0.7)))
        }
        drawText(readyToDock ? "БАЗА · СТЫКОВКА" : "БАЗА · 18", at: CGPoint(x: p.x, y: p.y + 84), color: OceanPalette.teal, in: &context)
        if readyToDock && hypot(engine.position.x - p.x, engine.position.y - p.y) < 100 {
            drawText("Отпусти стик", at: CGPoint(x: p.x, y: p.y + 101), color: OceanPalette.white, in: &context)
        }
    }

    private func drawMissionLandmark(_ landmark: MissionLandmark, in context: inout GraphicsContext) {
        let point = landmark.position
        let station = engine.mission == .currentStation
        let rect = CGRect(x: point.x - 38, y: point.y - 25, width: 76, height: 50)
        context.fill(Path(roundedRect: rect, cornerRadius: station ? 8 : 24), with: .color(OceanPalette.ink))
        context.stroke(Path(roundedRect: rect, cornerRadius: station ? 8 : 24), with: .color(OceanPalette.gold), lineWidth: 3)
        if station || landmark.kind == .signal {
            let radius: CGFloat = station ? 68 : MissionRun.scanRadius
            context.stroke(Path(ellipseIn: CGRect(x: point.x - radius, y: point.y - radius, width: radius * 2, height: radius * 2)),
                           with: .color(OceanPalette.gold.opacity(0.5)), style: StrokeStyle(lineWidth: 1.5, dash: [7, 6]))
        }
        let symbol: String = switch landmark.kind {
        case .station: "antenna.radiowaves.left.and.right"
        case .signal: "questionmark"
        case .drone: "camera.metering.spot"
        case .recovered: "checkmark"
        case .buoy: "lifepreserver"
        case .wreck: "ferry"
        }
        var icon = context.resolve(Image(systemName: symbol))
        icon.shading = .color(.white)
        context.draw(icon, in: CGRect(x: point.x - 14, y: point.y - 14, width: 28, height: 28))
        drawText(landmark.label, at: CGPoint(x: point.x, y: point.y + 46), color: .white, in: &context)
    }

    private func drawWreck(in context: inout GraphicsContext) {
        let p = engine.level.wreck
        context.drawLayer { layer in
            layer.translateBy(x: p.x, y: p.y + 49)
            layer.rotate(by: .degrees(-9))
            var hull = Path()
            hull.move(to: CGPoint(x: -95, y: -20))
            hull.addLine(to: CGPoint(x: -75, y: 25))
            hull.addLine(to: CGPoint(x: 54, y: 30))
            hull.addLine(to: CGPoint(x: 91, y: -13))
            hull.addLine(to: CGPoint(x: 22, y: -9))
            hull.addLine(to: CGPoint(x: 11, y: 9))
            hull.addLine(to: CGPoint(x: -8, y: -16))
            hull.closeSubpath()
            layer.fill(hull, with: .color(Color(red: 0.24, green: 0.28, blue: 0.27)))
            layer.stroke(hull, with: .color(OceanPalette.gold.opacity(0.25)), lineWidth: 1.5)
            layer.fill(Path(roundedRect: CGRect(x: -60, y: -46, width: 45, height: 30), cornerRadius: 4),
                       with: .color(Color(red: 0.15, green: 0.25, blue: 0.27)))
            for i in 0..<3 {
                layer.fill(Path(ellipseIn: CGRect(x: -52 + CGFloat(i) * 14, y: -36, width: 7, height: 7)), with: .color(OceanPalette.ink))
            }
            drawCoral(at: CGPoint(x: 45, y: 10), height: 38, direction: -1, color: OceanPalette.teal, in: &layer)
        }
        drawText("ASTER · ЗАТОНУВШИЙ КОРАБЛЬ", at: CGPoint(x: p.x - 8, y: p.y + 109), color: OceanPalette.muted, in: &context)
    }

    private func drawPickup(_ pickup: OceanPickup, in context: inout GraphicsContext) {
        let p = CGPoint(x: pickup.position.x, y: pickup.position.y + CGFloat(sin(time * 1.8 + Double(pickup.id))) * 3)
        let color: Color = pickup.kind == .crystal ? .cyan : pickup.kind == .shield ? OceanPalette.blue : (pickup.kind == .battery ? OceanPalette.teal : OceanPalette.gold)
        context.fill(Path(ellipseIn: CGRect(x: p.x - 32, y: p.y - 32, width: 64, height: 64)),
                     with: .radialGradient(Gradient(colors: [color.opacity(0.17), .clear]), center: p, startRadius: 2, endRadius: 32))
        switch pickup.kind {
        case .battery:
            let body = Path(roundedRect: CGRect(x: p.x - 8, y: p.y - 12, width: 16, height: 24), cornerRadius: 4)
            context.fill(body, with: .color(OceanPalette.ink))
            context.stroke(body, with: .color(color), lineWidth: 1.5)
            context.fill(Path(CGRect(x: p.x - 3, y: p.y - 16, width: 6, height: 4)), with: .color(color))
            for i in 0..<3 { context.fill(Path(CGRect(x: p.x - 4, y: p.y - 7 + CGFloat(i) * 6, width: 8, height: 3)), with: .color(color)) }
        case .shield:
            var shield = Path()
            shield.move(to: CGPoint(x: p.x, y: p.y - 15))
            shield.addLine(to: CGPoint(x: p.x + 12, y: p.y - 9))
            shield.addQuadCurve(to: CGPoint(x: p.x, y: p.y + 15), control: CGPoint(x: p.x + 13, y: p.y + 6))
            shield.addQuadCurve(to: CGPoint(x: p.x - 12, y: p.y - 9), control: CGPoint(x: p.x - 13, y: p.y + 6))
            shield.closeSubpath()
            context.fill(shield, with: .color(color.opacity(0.15)))
            context.stroke(shield, with: .color(color), lineWidth: 1.5)
        case .sample, .crystal:
            var crystal = Path()
            crystal.addLines([CGPoint(x: p.x, y: p.y - 12), CGPoint(x: p.x + 9, y: p.y), CGPoint(x: p.x, y: p.y + 12), CGPoint(x: p.x - 9, y: p.y)])
            crystal.closeSubpath()
            context.fill(crystal, with: .linearGradient(Gradient(colors: [OceanPalette.white, color]),
                startPoint: CGPoint(x: p.x - 8, y: p.y - 12), endPoint: CGPoint(x: p.x + 8, y: p.y + 12)))
        case .blackBox:
            let box = Path(roundedRect: CGRect(x: p.x - 18, y: p.y - 12, width: 36, height: 24), cornerRadius: 5)
            context.fill(box, with: .color(OceanPalette.ink))
            context.stroke(box, with: .color(color), lineWidth: 2)
            context.fill(Path(CGRect(x: p.x - 13, y: p.y - 10, width: 4, height: 20)), with: .color(color))
            context.fill(Path(CGRect(x: p.x + 9, y: p.y - 10, width: 4, height: 20)), with: .color(color))
            context.fill(Path(ellipseIn: CGRect(x: p.x - 2, y: p.y - 2, width: 4, height: 4)), with: .color(OceanPalette.teal))
        }
        let labels: [PickupKind: String] = [.crystal: "+10 КРИСТАЛЛОВ", .battery: "+30 ЭНЕРГИИ", .shield: "ЩИТ", .sample: "ОБРАЗЕЦ · 75", .blackBox: "ЧЁРНЫЙ ЯЩИК"]
        if hypot(engine.position.x - p.x, engine.position.y - p.y) < 200 || pickup.kind == .blackBox {
            drawText(labels[pickup.kind] ?? "", at: CGPoint(x: p.x, y: p.y + 31), color: color, in: &context)
        }
    }

    private func drawMine(_ mine: OceanMine, in context: inout GraphicsContext) {
        let p = mine.position
        if mine.phase == .spent { return }
        if mine.phase == .exploding {
            let progress = 1 - mine.timer / 0.65
            let radius = OceanMine.blastRadius * CGFloat(0.3 + progress * 0.7)
            let blast = Path(ellipseIn: CGRect(x: p.x - radius, y: p.y - radius, width: radius * 2, height: radius * 2))
            context.fill(blast, with: .color(OceanPalette.danger.opacity((1 - progress) * 0.2)))
            context.stroke(blast, with: .color(OceanPalette.gold.opacity(1 - progress)), lineWidth: 3)
            return
        }
        let armed = mine.phase == .armed
        let color = armed ? OceanPalette.danger : OceanPalette.muted
        if armed || engine.sonarRemaining > 0 {
            let radius = OceanMine.blastRadius
            let danger = Path(ellipseIn: CGRect(x: p.x - radius, y: p.y - radius, width: radius * 2, height: radius * 2))
            context.fill(danger, with: .color(OceanPalette.danger.opacity(armed ? 0.055 : 0.025)))
            context.stroke(danger, with: .color(OceanPalette.danger.opacity(armed ? 0.6 : 0.25)),
                           style: StrokeStyle(lineWidth: 1, dash: [4, 5]))
        }
        for i in 0..<8 {
            let a = CGFloat(i) * .pi / 4
            var spike = Path()
            spike.move(to: CGPoint(x: p.x + cos(a) * 12, y: p.y + sin(a) * 12))
            spike.addLine(to: CGPoint(x: p.x + cos(a) * 21, y: p.y + sin(a) * 21))
            context.stroke(spike, with: .color(color), style: StrokeStyle(lineWidth: 3, lineCap: .round))
        }
        let body = Path(ellipseIn: CGRect(x: p.x - 14, y: p.y - 14, width: 28, height: 28))
        context.fill(body, with: .color(OceanPalette.ink))
        context.stroke(body, with: .color(color), lineWidth: 2)
        context.fill(Path(ellipseIn: CGRect(x: p.x - 4, y: p.y - 4, width: 8, height: 8)),
                     with: .color(OceanPalette.danger.opacity(armed ? 1 : 0.65)))
        if armed {
            var fuse = Path()
            fuse.addArc(center: p, radius: 29, startAngle: .degrees(-90),
                        endAngle: .degrees(-90 + 360 * mine.timer / OceanMine.fuse), clockwise: false)
            context.stroke(fuse, with: .color(OceanPalette.danger), style: StrokeStyle(lineWidth: 3, lineCap: .round))
        }
    }

    private func drawSonar(in context: inout GraphicsContext) {
        guard !reduceMotion else { return }
        let p = engine.screenPoint(engine.position)
        let progress = 1 - engine.sonarRemaining / 5
        let radius = CGFloat(progress) * 760
        context.stroke(Path(ellipseIn: CGRect(x: p.x - radius, y: p.y - radius, width: radius * 2, height: radius * 2)),
                       with: .color(OceanPalette.teal.opacity((1 - progress) * 0.5)), lineWidth: 1.5)
    }

    /// The expedition takes place after the external lighting failed: the
    /// world remains legible only inside the submarine's headlight cone.
    private func drawLowVisibility(in context: inout GraphicsContext, size: CGSize) {
        let center = engine.screenPoint(engine.position)
        let pitch = CGFloat(engine.submarineRotationRadians)
        let direction = CGVector(dx: cos(pitch) * engine.facing, dy: sin(pitch))
        let perpendicular = CGVector(dx: -direction.dy, dy: direction.dx)
        let range = engine.headlightRange
        let spread = engine.isLightBoostActive ? range * 0.43 : range * 0.36

        func cone(length: CGFloat, width: CGFloat) -> Path {
            let start = CGPoint(x: center.x + direction.dx * 24, y: center.y + direction.dy * 24)
            let near = width * 0.08
            let end = CGPoint(x: start.x + direction.dx * length, y: start.y + direction.dy * length)
            var path = Path()
            path.move(to: CGPoint(x: start.x + perpendicular.dx * near, y: start.y + perpendicular.dy * near))
            path.addQuadCurve(to: CGPoint(x: end.x + perpendicular.dx * width, y: end.y + perpendicular.dy * width),
                              control: CGPoint(x: start.x + direction.dx * length * 0.62 + perpendicular.dx * width * 0.48,
                                               y: start.y + direction.dy * length * 0.62 + perpendicular.dy * width * 0.48))
            path.addLine(to: CGPoint(x: end.x - perpendicular.dx * width, y: end.y - perpendicular.dy * width))
            path.addQuadCurve(to: CGPoint(x: start.x - perpendicular.dx * near, y: start.y - perpendicular.dy * near),
                              control: CGPoint(x: start.x + direction.dx * length * 0.62 - perpendicular.dx * width * 0.48,
                                               y: start.y + direction.dy * length * 0.62 - perpendicular.dy * width * 0.48))
            path.closeSubpath()
            return path
        }

        context.drawLayer { darkness in
            darkness.fill(Path(CGRect(origin: .zero, size: size)), with: .color(Color.black.opacity(0.91)))
            darkness.blendMode = .destinationOut
            darkness.fill(cone(length: range * 1.07, width: spread * 1.12), with: .color(.white.opacity(0.30)))
            darkness.fill(cone(length: range, width: spread), with: .linearGradient(
                Gradient(colors: [.white, .white.opacity(0.88), .white.opacity(0.38)]),
                startPoint: center,
                endPoint: CGPoint(x: center.x + direction.dx * range, y: center.y + direction.dy * range)))
            let haloRadius: CGFloat = engine.isLightBoostActive ? 116 : 72
            darkness.fill(Path(ellipseIn: CGRect(x: center.x - haloRadius, y: center.y - haloRadius,
                                                 width: haloRadius * 2, height: haloRadius * 2)),
                          with: .radialGradient(Gradient(colors: [.white, .white.opacity(0.78), .clear]),
                                                center: center, startRadius: 12, endRadius: haloRadius))
        }

        context.fill(cone(length: range, width: spread), with: .linearGradient(
            Gradient(colors: [OceanPalette.gold.opacity(engine.isLightBoostActive ? 0.12 : 0.07), .clear]),
            startPoint: center,
            endPoint: CGPoint(x: center.x + direction.dx * range, y: center.y + direction.dy * range)))
    }

    private func drawText(_ text: String, at point: CGPoint, color: Color, in context: inout GraphicsContext) {
        context.draw(Text(text).font(.system(size: 9, weight: .semibold, design: .monospaced)).foregroundStyle(color), at: point)
    }

    private func drawCoral(at p: CGPoint, height: CGFloat, direction: CGFloat, color: Color, in context: inout GraphicsContext) {
        var path = Path()
        path.move(to: p)
        path.addQuadCurve(to: CGPoint(x: p.x + 3, y: p.y + height * direction), control: CGPoint(x: p.x - 4, y: p.y + height * direction * 0.6))
        path.move(to: CGPoint(x: p.x, y: p.y + height * direction * 0.4))
        path.addLine(to: CGPoint(x: p.x - 9, y: p.y + height * direction * 0.73))
        path.addLine(to: CGPoint(x: p.x - 10, y: p.y + height * direction))
        path.move(to: CGPoint(x: p.x + 1, y: p.y + height * direction * 0.65))
        path.addLine(to: CGPoint(x: p.x + 10, y: p.y + height * direction * 0.88))
        context.stroke(path, with: .color(color.opacity(0.8)), style: StrokeStyle(lineWidth: 2.5, lineCap: .round, lineJoin: .round))
    }

    private func drawSubmarine(in context: inout GraphicsContext, size: CGSize) {
        let ready = engine.state == .ready
        let center = ready ? CGPoint(x: size.width / 2, y: size.height * 0.43 + CGFloat(sin(time * 1.7)) * 5) : engine.screenPoint(engine.position)
        let boatScale: CGFloat = ready ? 1.6 : 0.86
        let facing: CGFloat = ready ? 1 : engine.facing
        for index in 0..<7 {
            let phase = (CGFloat(time) * (engine.isThrustActive ? 65 : 34) + CGFloat(index) * 14)
                .truncatingRemainder(dividingBy: 100)
            let radius = (1 + phase / 55) * boatScale
            let x = center.x - (48 + phase * 0.65) * boatScale * facing
            let y = center.y + CGFloat(sin(Double(phase) * 0.06 + Double(index))) * 8 - phase * 0.09
            context.stroke(Path(ellipseIn: CGRect(x: x, y: y, width: radius * 2, height: radius * 2)),
                           with: .color(OceanPalette.teal.opacity(Double(1 - phase / 100) * 0.4)), lineWidth: 0.8)
        }
        if !ready && engine.hasShield {
            context.stroke(Path(ellipseIn: CGRect(x: center.x - 38, y: center.y - 36, width: 76, height: 72)),
                           with: .color(OceanPalette.blue.opacity(0.65)), lineWidth: 1.5)
        }
        context.drawLayer { layer in
            layer.translateBy(x: center.x, y: center.y)
            layer.rotate(by: .radians(ready ? -0.055 : engine.submarineRotationRadians * Double(facing)))
            layer.scaleBy(x: boatScale * facing, y: boatScale)
            if !ready && engine.invulnerability > 0 { layer.opacity = reduceMotion ? 0.65 : 0.45 + abs(sin(time * 18)) * 0.55 }
            if !nightExpedition {
            let beamLength: CGFloat = ready ? 186 : engine.headlightRange / boatScale
            let beamSpread: CGFloat = ready ? 59 : beamLength * (engine.isLightBoostActive ? 0.43 : 0.36)
            var beam = Path()
            beam.move(to: CGPoint(x: 32, y: -3))
            beam.addLine(to: CGPoint(x: beamLength, y: -beamSpread))
            beam.addQuadCurve(to: CGPoint(x: beamLength, y: beamSpread),
                              control: CGPoint(x: beamLength * 1.1, y: 0))
            beam.addLine(to: CGPoint(x: 32, y: 6))
            beam.closeSubpath()
            layer.fill(beam, with: .linearGradient(
                Gradient(colors: [OceanPalette.gold.opacity(engine.isLightBoostActive ? 0.22 : 0.12), .clear]),
                startPoint: CGPoint(x: 32, y: 0), endPoint: CGPoint(x: beamLength, y: 0)))
            }

            let style = engine.selectedStyle
            let paint: Color = switch style {
            case .classic: OceanPalette.gold
            case .neon: .purple
            case .flames: .red
            case .chrome: .gray
            }
            let darkGold = Color(red: 0.63, green: 0.34, blue: 0.12)
            var fin = Path()
            fin.move(to: CGPoint(x: -23, y: -8))
            fin.addLine(to: CGPoint(x: -42, y: -23))
            fin.addLine(to: CGPoint(x: -39, y: 20))
            fin.addLine(to: CGPoint(x: -22, y: 10))
            fin.closeSubpath()
            layer.fill(fin, with: .color(darkGold))
            layer.fill(Path(roundedRect: CGRect(x: -46, y: -3, width: 15, height: 6), cornerRadius: 3), with: .color(OceanPalette.muted))
            let propellerHeight = CGFloat(7 + abs(sin(time * (engine.isThrustActive ? 35 : 19))) * 20)
            layer.fill(Path(roundedRect: CGRect(x: -47, y: -propellerHeight / 2, width: 4, height: propellerHeight), cornerRadius: 2),
                       with: .color(OceanPalette.white.opacity(0.9)))
            let cabin = Path(roundedRect: CGRect(x: -14, y: -27, width: 28, height: 19), cornerRadius: 7)
            layer.fill(cabin, with: .linearGradient(Gradient(colors: [OceanPalette.gold, darkGold]),
                startPoint: CGPoint(x: 0, y: -27), endPoint: CGPoint(x: 0, y: -9)))
            var scope = Path()
            scope.move(to: CGPoint(x: -2, y: -26))
            scope.addLine(to: CGPoint(x: -2, y: -36))
            scope.addQuadCurve(to: CGPoint(x: 2, y: -40), control: CGPoint(x: -2, y: -40))
            scope.addLine(to: CGPoint(x: 9, y: -40))
            layer.stroke(scope, with: .color(OceanPalette.gold), style: StrokeStyle(lineWidth: 4, lineCap: .round))
            layer.fill(Path(roundedRect: CGRect(x: 7, y: -43, width: 5, height: 6), cornerRadius: 1.5), with: .color(OceanPalette.ink))
            let hull = Path(roundedRect: CGRect(x: -34, y: -18, width: 72, height: 37), cornerRadius: 18.5)
            layer.fill(hull, with: .linearGradient(Gradient(colors: [paint.opacity(0.6), paint, paint.opacity(0.8)]),
                startPoint: CGPoint(x: 0, y: -18), endPoint: CGPoint(x: 0, y: 21)))
            layer.stroke(hull, with: .color(Color(red: 1, green: 0.88, blue: 0.59).opacity(0.65)), lineWidth: 0.8)
            if style == .neon {
                layer.stroke(hull, with: .color(OceanPalette.teal), lineWidth: 3)
                layer.fill(Path(roundedRect: CGRect(x: -25, y: 22, width: 50, height: 4), cornerRadius: 2), with: .color(OceanPalette.teal))
            } else if style == .flames {
                var flames = Path()
                flames.move(to: CGPoint(x: -30, y: 12))
                for x in stride(from: -25, through: 20, by: 15) {
                    flames.addLine(to: CGPoint(x: x + 12, y: -13))
                    flames.addLine(to: CGPoint(x: x + 6, y: 12))
                }
                flames.closeSubpath()
                layer.fill(flames, with: .color(OceanPalette.gold))
            } else if style == .chrome {
                for x: CGFloat in [-24, 14] {
                    let speaker = Path(roundedRect: CGRect(x: x, y: -36, width: 16, height: 19), cornerRadius: 3)
                    layer.fill(speaker, with: .color(OceanPalette.ink))
                    layer.stroke(Path(ellipseIn: CGRect(x: x + 3, y: -32, width: 10, height: 10)), with: .color(.white), lineWidth: 2)
                }
            }
            let shine = Path(roundedRect: CGRect(x: -23, y: -14, width: 39, height: 3), cornerRadius: 1.5)
            layer.fill(shine, with: .color(.white.opacity(0.38)))
            for x: CGFloat in [-13, 11] {
                layer.fill(Path(ellipseIn: CGRect(x: x - 9, y: -9, width: 18, height: 18)), with: .color(darkGold))
                layer.fill(Path(ellipseIn: CGRect(x: x - 7.5, y: -7.5, width: 15, height: 15)), with: .color(Color(red: 0.98, green: 0.88, blue: 0.61)))
                let glass = Path(ellipseIn: CGRect(x: x - 5.8, y: -5.8, width: 11.6, height: 11.6))
                layer.fill(glass, with: .linearGradient(Gradient(colors: [Color(red: 0.10, green: 0.32, blue: 0.39), OceanPalette.teal]),
                    startPoint: CGPoint(x: x, y: -6), endPoint: CGPoint(x: x, y: 6)))
                layer.fill(Path(ellipseIn: CGRect(x: x - 3.7, y: -3.7, width: 3.5, height: 2.5)), with: .color(.white.opacity(0.7)))
            }
            for x: CGFloat in [-24, -2, 24] {
                layer.fill(Path(ellipseIn: CGRect(x: x, y: 12, width: 1.5, height: 1.5)), with: .color(darkGold.opacity(0.8)))
            }
            layer.fill(Path(roundedRect: CGRect(x: -9, y: 16, width: 26, height: 5), cornerRadius: 2), with: .color(darkGold))
            layer.fill(Path(roundedRect: CGRect(x: 33, y: -5, width: 6, height: 10), cornerRadius: 3), with: .color(Color(red: 1, green: 0.94, blue: 0.73)))
        }
    }

}

// MARK: - VoiceOverAnnouncer.swift

/// Speech consumes simulation events; it never blocks steering or the fixed physics step.
@MainActor
final class VoiceOverAnnouncer: ObservableObject {
    enum Priority: Int { case beacon, event, danger }
    private struct Message {
        let key: String
        let text: String
        let priority: Priority
    }
    private var subscriptions = Set<AnyCancellable>()
    private var pending: [Message] = []
    private var delivery: Task<Void, Never>?
    private var beacon: SituationSummary?
    private var lastBeacon = -Double.infinity
    private var lastDanger = -Double.infinity
    private var seen: [String: TimeInterval] = [:]
    private var proximity: (id: String, level: Int)?
    private weak var engine: GameEngine?
    private let voiceOverRunning: () -> Bool
    private let post: (NSAttributedString) -> Void
    private let now: () -> TimeInterval

    init(engine: GameEngine,
         voiceOverRunning: @escaping () -> Bool = { UIAccessibility.isVoiceOverRunning },
         now: @escaping () -> TimeInterval = { ProcessInfo.processInfo.systemUptime },
         post: @escaping (NSAttributedString) -> Void = {
             UIAccessibility.post(notification: .announcement, argument: $0)
         }) {
        self.engine = engine
        self.voiceOverRunning = voiceOverRunning
        self.now = now
        self.post = post
        engine.events.sink { [weak self] event in self?.receive(event) }.store(in: &subscriptions)
        NotificationCenter.default.publisher(for: UIAccessibility.voiceOverStatusDidChangeNotification)
            .receive(on: RunLoop.main)
            .sink { [weak self] _ in self?.reset() }.store(in: &subscriptions)
    }

    private func reset() {
        delivery?.cancel()
        delivery = nil
        pending.removeAll()
        seen.removeAll()
        beacon = nil
        proximity = nil
        lastBeacon = -.infinity
        lastDanger = -.infinity
    }

    private func receive(_ event: GameEvent) {
        guard voiceOverRunning() else {
            reset()
            return
        }
        switch event {
        case .diagnostic, .runStarted, .runEnded: break
        case .danger(let text): enqueue(key: "danger", text: text, priority: .danger)
        case .speak(let text): enqueue(key: "speech:\(text)", text: text, priority: .event)
        case .energyLow:
            enqueue(key: "energy", text: A11yL10n.text("event.energy.low", defaultValue: "Внимание. Энергия ниже 25 процентов."), priority: .danger)
        case .objectiveChanged:
            // The same transition includes the localized black-box pickup event.
            break
        case .success, .record:
            // Completion is spoken as one summary after score and record have been stored.
            break
        case .stateChanged(let state):
            reset()
            let text: String
            switch state {
            case .ready: return
            case .playing:
                text = A11yL10n.text("speech.playing", defaultValue: "Экспедиция продолжается")
            case .paused:
                text = A11yL10n.text("speech.paused", defaultValue: "Пауза")
            case .completed:
                guard let engine else { return }
                text = engine.outcome == .returned
                    ? "Вернулись без выполнения задания. Доставлено: \(engine.score). Следующая экспедиция не открыта."
                    : A11yL10n.format("speech.completed", defaultValue: "Груз доставлен: %lld. Рекорд: %lld.", Int64(engine.score), Int64(engine.bestScore))
            case .gameOver:
                text = engine?.failureReason == .energy
                    ? A11yL10n.text("a11y.result.energy.detail", defaultValue: "Заряд закончился. Груз остался на глубине.")
                    : A11yL10n.text("a11y.result.hull.detail", defaultValue: "Корпус не выдержал. Груз остался на глубине.")
            }
            enqueue(key: "state", text: text, priority: .event)
        case .situation(let summary):
            warnAboutApproach(summary.danger)
            let time = now()
            guard time - lastBeacon >= 5, time - lastDanger >= 2 else { return }
            if let old = beacon {
                guard abs(old.targetDistance - summary.targetDistance) >= 20
                        || old.targetCourse != summary.targetCourse || old.returning != summary.returning
                        || old.danger?.id != summary.danger?.id || old.find?.id != summary.find?.id
                        || old.currentCourse != summary.currentCourse
                        || old.caveTimeRemaining == nil && summary.caveTimeRemaining != nil
                        || old.caveTimeRemaining != nil && summary.caveTimeRemaining == nil else { return }
            }
            beacon = summary
            lastBeacon = time
            enqueue(key: "beacon", text: Self.format(summary), priority: .beacon)
        }
    }

    private func warnAboutApproach(_ contact: SituationSummary.Contact?) {
        guard let contact else { proximity = nil; return }
        let level = contact.distance <= 8 ? 3 : contact.distance <= 16 ? 2 : contact.distance <= 30 ? 1 : 0
        let previous = proximity
        proximity = (contact.id, level)
        guard level > 0, previous?.id != contact.id || level > (previous?.level ?? 0) else { return }
        let text = A11yL10n.format("speech.danger", defaultValue: "Опасность. %@, %lld метров, %@.", contact.name, Int64(contact.distance), contact.course.label)
        enqueue(key: "approach", text: text, priority: .danger)
    }

    func describeSurroundings() {
        guard voiceOverRunning(), let engine, engine.state == .playing else { return }
        deliver(Self.format(engine.situationSummary), queued: false)
    }

    func describeMap() {
        guard voiceOverRunning(), let engine, engine.state == .paused else { return }
        deliver(engine.sectorOverview, queued: false)
    }

    private func enqueue(key: String, text: String, priority: Priority) {
        let time = now()
        // Actual danger events are edges from the engine: a second mine must speak again.
        if priority != .danger {
            seen = seen.filter { time - $0.value < 2 }
            guard seen[key] == nil else { return }
            seen[key] = time
        } else {
            lastDanger = time
            pending.removeAll { $0.priority == .beacon }
            delivery?.cancel()
            delivery = nil
        }
        pending.removeAll { $0.key == key }
        pending.append(Message(key: key, text: text, priority: priority))
        drain()
    }

    private func deliver(_ text: String, queued: Bool) {
        let speech = NSMutableAttributedString(string: text)
        speech.addAttribute(.accessibilitySpeechQueueAnnouncement, value: queued,
                            range: NSRange(location: 0, length: speech.length))
        post(speech)
    }

    private func drain() {
        guard delivery == nil, !pending.isEmpty, voiceOverRunning() else { return }
        let priority = pending.map(\.priority.rawValue).max()!
        let index = pending.firstIndex { $0.priority.rawValue == priority }!
        let message = pending.remove(at: index)
        deliver(message.text, queued: message.priority != .danger)
        delivery = Task { [weak self] in
            do { try await Task.sleep(for: .seconds(2)) } catch { return }
            guard let self else { return }
            delivery = nil
            drain()
        }
    }

    static func format(_ summary: SituationSummary) -> String {
        var parts: [String]
        if let remaining = summary.caveTimeRemaining {
            parts = [A11yL10n.format("speech.cave", defaultValue: "Пещера спрута. Продержись ещё %lld секунд.", Int64(remaining))]
        } else {
            parts = [A11yL10n.format("speech.instruments", defaultValue: "Глубина %lld метров, скорость %lld метров в секунду.", Int64(summary.depth), Int64(summary.speed)),
                     A11yL10n.format("speech.target", defaultValue: "%@: %lld метров, %@.",
                                    summary.targetName ?? (summary.returning ? A11yL10n.contactKind(.base) : A11yL10n.pickupName(.blackBox)),
                                    Int64(summary.targetDistance), summary.targetCourse.label)]
        }
        for contact in [summary.danger, summary.find].compactMap({ $0 }) {
            parts.append(A11yL10n.format("speech.contact", defaultValue: "%@: %lld метров, %@.", contact.name, Int64(contact.distance), contact.course.label))
        }
        if let course = summary.currentCourse {
            parts.append(A11yL10n.format("speech.current", defaultValue: "Течение: %@, %lld метров в секунду.", course.label, Int64(summary.currentSpeed)))
        }
        return parts.joined(separator: " ")
    }
}

// MARK: - GameView.swift

struct ContentView: View {
    @StateObject private var recovery: ExpeditionRecovery
    @State private var showingEvents = false
    @State private var confirmNewGame = false
    @StateObject private var engine: GameEngine
    @StateObject private var recorder: BlackBoxRecorder
    @StateObject private var captain = CaptainNote()
    @State private var showingBlackBox = false
    @State private var showingArchives = false
    @StateObject private var announcer: VoiceOverAnnouncer
    @AccessibilityFocusState private var focusedControl: String?
    @Environment(\.scenePhase) private var scenePhase
    @Environment(\.dynamicTypeSize) private var dynamicTypeSize
    @Environment(\.accessibilityVoiceOverEnabled) private var voiceOverEnabled
    @AppStorage("podlodkaDive.voiceOverButtons") private var voiceOverButtons = false
    @State private var showingCampaign = false
    @State private var showingSettings = false
    @State private var showingHelp = false
    @State private var confirmingAbandon = false
    @State private var showingMap = false
    @State private var showingCrewJournal = false
    @State private var crewVisibleLimit = 50
    @AppStorage("podlodkaDive.nightExpedition") private var nightExpedition = false
    @State private var showingGarage = false
    @State private var showingJournal = false
    @State private var showingReplay = false
    @State private var showingBureau = false
    @State private var showingCaptainJournal = false
    @State private var pendingStyle: SubmarineStyle?
    @State private var garageMessage = ""

    init(engine: GameEngine = GameEngine()) {
        let arguments = ProcessInfo.processInfo.arguments
        let recovery = ExpeditionRecovery(engine: engine)
        engine.recovery = recovery
        _recovery = StateObject(wrappedValue: recovery)
        _engine = StateObject(wrappedValue: engine)
        _recorder = StateObject(wrappedValue: BlackBoxRecorder(engine: engine))
        _showingMap = State(initialValue: arguments.contains("map"))
        _announcer = StateObject(wrappedValue: VoiceOverAnnouncer(engine: engine))
    }

    var body: some View {
        GeometryReader { proxy in
            ZStack {
                GameCanvas(engine: engine, nightExpedition: nightExpedition).accessibilityHidden(true)
                if nightExpedition, engine.state != .ready {
                    Color.black.opacity(0.84)
                        .ignoresSafeArea()
                        .allowsHitTesting(false)
                        .accessibilityHidden(true)
                }
                if engine.state == .ready {
                    ScrollView {
                        welcome(size: proxy.size, insets: proxy.safeAreaInsets)
                            .frame(minHeight: proxy.size.height)
                    }
                } else {
                    if engine.state == .playing {
                        if dynamicTypeSize.isAccessibilitySize {
                            largeTextInstruments(insets: proxy.safeAreaInsets)
                        } else {
                            instruments(insets: proxy.safeAreaInsets)
                            controls(insets: proxy.safeAreaInsets)
                        }
                    }
                    if engine.state != .playing {
                        OceanPalette.ink.opacity(0.78).ignoresSafeArea()
                        if showingMap {
                            ScrollView {
                                mapPanel(height: proxy.size.height)
                                    .padding(.vertical, max(proxy.safeAreaInsets.top, 48))
                            }
                        } else {
                            ScrollView {
                                resultPanel.padding(.vertical, max(proxy.safeAreaInsets.top, 48))
                                    .frame(minHeight: proxy.size.height)
                            }
                        }
                    }
                }
            }
            .onAppear {
                engine.resize(to: proxy.size)
#if DEBUG
                let arguments = ProcessInfo.processInfo.arguments
                if let marker = arguments.firstIndex(of: "-accessibilityAuditState"), arguments.indices.contains(marker + 1) {
                    engine.prepareAccessibilityAuditState(arguments[marker + 1])
                }
#endif
                ReturnInbox.shared.connect { url, event in openReturnURL(url, eventID: event) }
                if engine.state != .ready { engine.startLoop() }
            }
            .onDisappear { engine.stopLoop() }
            .onChange(of: proxy.size) { _, size in engine.resize(to: size) }
        }
        .onOpenURL { openReturnURL($0) }
        .sheet(isPresented: $showingEvents, onDismiss: { focusedControl = "surfaceMenu" }) {
            ReturnEventsView(recovery: recovery) { openReturnURL($0) }
        }
        .onChange(of: showingEvents) { _, visible in engine.navigate(to: visible ? "Events" : journalReturnScreen, reason: "events") }
        .alert("Возвращение в экспедицию", isPresented: Binding(get: { recovery.message != nil }, set: { if !$0 { recovery.message = nil } })) {
            Button("Понятно") { recovery.message = nil }
        } message: { Text(recovery.message ?? "") }
        .confirmationDialog("Заменить активную экспедицию сохранённой?", isPresented: Binding(get: { recovery.replacement != nil }, set: { if !$0 { recovery.replacement = nil } })) {
            Button("Открыть сохранение", role: .destructive) {
                if let route = recovery.replacement { recovery.open(route.url, confirmed: true) }
                recovery.replacement = nil
            }
            Button("Отмена", role: .cancel) { recovery.replacement = nil }
        }
        .confirmationDialog("Начать новую экспедицию? Сохранение будет удалено.", isPresented: $confirmNewGame) {
            Button("Начать новую", role: .destructive) { engine.startGame() }
            Button("Отмена", role: .cancel) { }
        }
        .ignoresSafeArea()
        .statusBarHidden()
        .persistentSystemOverlays(.hidden)
        .tint(OceanPalette.teal)
        .onChange(of: dynamicTypeSize) { _, _ in engine.setSteering(.zero) }
        .onChange(of: voiceOverEnabled) { _, _ in engine.setSteering(.zero) }
        .onChange(of: voiceOverButtons) { _, _ in engine.setSteering(.zero) }
        .onChange(of: scenePhase) { _, phase in
            if phase != .active {
                captain.finish(recorder: recorder)
                engine.pause()
                if phase == .background { recovery.save(exiting: true) }
                engine.captainLogger.flush()
                let backgroundTask = UIApplication.shared.beginBackgroundTask(withName: "Expedition flush")
                Task {
                    await engine.flushJournal()
                    await recorder.drain()
                    if backgroundTask != .invalid { UIApplication.shared.endBackgroundTask(backgroundTask) }
                }
            }
        }
        .onChange(of: showingMap) { _, visible in engine.navigate(to: visible ? "Map" : (engine.state == .playing ? "Game" : "Pause"), reason: visible ? "openMap" : "closeMap") }
        .sensoryFeedback(.selection, trigger: engine.pickupCount)
        .sensoryFeedback(.error, trigger: engine.damageCount)
        .sensoryFeedback(.warning, trigger: engine.eventCount)
        .sensoryFeedback(.success, trigger: engine.state == .completed)
        .preferredColorScheme(.dark)
        .task(id: "\(engine.state)-\(showingMap)") {
            let destination: String?
            switch engine.state {
            case .ready: destination = "startDive"
            case .playing: destination = "steeringPad"
            case .paused: destination = showingMap ? "closeMap" : "resumeDive"
            case .completed, .gameOver: destination = "retryDive"
            }
            try? await Task.sleep(for: .milliseconds(250))
            guard !Task.isCancelled, UIAccessibility.isVoiceOverRunning else { return }
            UIAccessibility.post(notification: .screenChanged, argument: nil)
            focusedControl = destination
            if showingMap { announcer.describeMap() }
        }
        .onChange(of: showingGarage) { _, visible in engine.navigate(to: visible ? "Garage" : "Welcome", reason: visible ? "openGarage" : "closeGarage") }
        .onChange(of: showingJournal) { _, visible in engine.navigate(to: visible ? "Journal" : journalReturnScreen, reason: visible ? "openJournal" : "closeJournal") }
        .onChange(of: showingReplay) { _, visible in engine.navigate(to: visible ? "Replay" : journalReturnScreen, reason: visible ? "openReplay" : "closeReplay") }
        .onChange(of: showingCampaign) { _, visible in
            engine.navigate(to: visible ? "Campaign" : "Welcome", reason: visible ? "openCampaign" : "closeCampaign")
            recorder.flow(visible ? "campaign" : "ready")
        }
        .sheet(isPresented: $showingSettings) { settingsPanel }
        .sheet(isPresented: $showingHelp) { helpPanel }
        .fullScreenCover(isPresented: $showingCampaign) { CampaignView(engine: engine) }
        .alert("Сохранить и выйти?", isPresented: $confirmingAbandon) {
            Button("Сохранить и выйти") { showingMap = false; engine.returnToMenu() }
                .accessibilityIdentifier("confirmAbandon")
            Button("Остаться", role: .cancel) {}.accessibilityIdentifier("cancelAbandon")
        } message: {
            Text("Экспедиция сохранится. Её можно будет продолжить с этого места.")
        }
        .fullScreenCover(isPresented: $showingArchives) { archiveLibrary }
        .sheet(isPresented: $showingGarage) { garagePanel }
        .sheet(isPresented: $showingReplay) {
            if let id = engine.expeditionId {
                NavigationStack {
                    ExpeditionReplayView(expeditionId: id)
                        .toolbar { Button("Закрыть") { showingReplay = false } }
                }
            }
        }
        .onChange(of: showingMap) { _, value in recorder.flow(value ? "map" : String(describing: engine.state)) }
        .onChange(of: showingGarage) { _, value in recorder.flow(value ? "garage" : "ready") }
        .onChange(of: showingBlackBox) { _, value in recorder.flow(value ? "journal" : String(describing: engine.state)) }
        .onChange(of: engine.state) { _, state in
            if state == .ready { engine.stopLoop() } else { engine.startLoop() }
            if state != .playing { captain.finish(recorder: recorder) }
        }

    }

    private func openReturnURL(_ url: URL, eventID: UUID? = nil) {
        showingMap = false
        showingCampaign = false
        showingSettings = false
        showingHelp = false
        showingEvents = false
        showingArchives = false
        showingGarage = false
        showingJournal = false
        showingReplay = false
        showingBureau = false
        showingCaptainJournal = false
        showingBlackBox = false
        showingCrewJournal = false
        recovery.open(url, pushEventID: eventID)
    }

    private var journalReturnScreen: String {
        switch engine.state {
        case .ready: "Welcome"
        case .playing: "Game"
        case .paused: showingMap ? "Map" : "Pause"
        case .completed, .gameOver: "Result"
        }
    }

    private var voiceNoteControls: some View {
        VStack {
            if captain.recording { Text(captain.text).font(.body).lineLimit(3) }
            if let error = captain.error { Text(error).font(.body) }
            Button { Task { await captain.toggle(recorder: recorder) } } label: {
                Label(captain.recording ? "Закончить заметку" : "Заметка капитана",
                      systemImage: captain.recording ? "stop.circle" : "mic")
            }
            .disabled(captain.busy).buttonStyle(.bordered).controlSize(.large)
            .tint(.white).background(.black, in: Capsule()).accessibilityIdentifier("captainNote")
        }.padding(.bottom, 8)
    }

    private var journalButton: some View {
        Button { showingArchives = true } label: {
            Label("Журналы экспедиции", systemImage: "books.vertical")
                .font(.body).foregroundStyle(Color.white)
                .frame(maxWidth: .infinity, minHeight: 44).contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .padding(8)
        .background(OceanPalette.ink, in: RoundedRectangle(cornerRadius: 12))
        .accessibilityIdentifier("openJournal")
    }

    private var archiveLibrary: some View {
        NavigationStack {
            List {
                Button("Закрыть") { showingArchives = false }.font(.body).frame(minHeight: 44).accessibilityIdentifier("closeArchives")
                Button("События, реплей и граф") {
                    Task { await engine.flushJournal(); showingJournal = true }
                }.accessibilityIdentifier("openTelemetry")
                Button("Подводное бюро расследований") { showingBureau = true }
                    .accessibilityIdentifier("openBureau")
                Button("Вахтенный журнал") { showingCaptainJournal = true }
                    .accessibilityIdentifier("openCaptainJournal")
                Button("Чёрный ящик и заметки") {
                    Task { await recorder.drain(); showingBlackBox = true }
                }.accessibilityIdentifier("openBlackBox")
                Button("Реплики экипажа") { showingCrewJournal = true }
                    .accessibilityIdentifier("openCrewJournal")
            }
            .foregroundStyle(.primary)
            .navigationTitle("Журналы экспедиции")
        }
        .fullScreenCover(isPresented: $showingJournal) { ExpeditionJournalView() }
        .fullScreenCover(isPresented: $showingBureau) { BureauView(journal: .shared) }
        .fullScreenCover(isPresented: $showingCaptainJournal) { CaptainJournalView(logger: engine.captainLogger) }
        .fullScreenCover(isPresented: $showingBlackBox) { BlackBoxJournal() }
        .fullScreenCover(isPresented: $showingCrewJournal) { journalPanel }
    }

    private func largeTextInstruments(insets: EdgeInsets) -> some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 20) {
                Text(engine.objectiveText).font(.title2).accessibilityAddTraits(.isHeader)
                Text(engine.missionStatus).font(.body)
                Text(engine.accessibilityStatus).font(.body)
                Text(engine.sectorOverview).font(.body)
                SteeringPad(onInput: engine.setSteering, steering: engine.steering,
                            contacts: engine.sonarContacts, onSummary: announcer.describeSurroundings)
                    .frame(height: 158).accessibilityFocused($focusedControl, equals: "steeringPad")
                Button("Что вокруг?", action: announcer.describeSurroundings)
                Button("Сонар", action: engine.activateSonar)
                    .disabled(!engine.canSonar).accessibilityIdentifier("sonar")
                Button("Форсаж", action: engine.activateBoost)
                    .disabled(!engine.canBoost).accessibilityIdentifier("boost")
                Button("Усилить фары", action: engine.activateLightBoost)
                    .disabled(!engine.canLightBoost).accessibilityIdentifier("lightBoost")
                if engine.zone == .ocean {
                    Button("Карта экспедиции", action: openMap).accessibilityIdentifier("openMap")
                }
                voiceNoteControls
                Button("Пауза", action: engine.pause).accessibilityIdentifier("pauseDive")
            }
            .buttonStyle(.bordered).controlSize(.large)
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding(24).padding(.top, max(insets.top, 48)).padding(.bottom, max(insets.bottom, 24))
        }
        .background(OceanPalette.ink)
    }

    private func welcome(size: CGSize, insets: EdgeInsets) -> some View {
        VStack(spacing: 24) {
            HStack {
                Text("PODLODKA / 18")
                    .font(.system(.headline, design: .monospaced)).foregroundStyle(.white)
                Spacer()
                Menu {
                    Button("События", systemImage: "clock.arrow.circlepath") { showingEvents = true }
                        .accessibilityIdentifier("openEvents")
                    Button("Гараж", systemImage: "wrench.and.screwdriver") {
                        garageMessage = ""
                        showingGarage = true
                    }.accessibilityIdentifier("openGarage")
                    Button("Журналы экспедиции", systemImage: "books.vertical") {
                        showingArchives = true
                    }.accessibilityIdentifier("openJournal")
                    Button("Настройки", systemImage: "slider.horizontal.3") {
                        showingSettings = true
                    }.accessibilityIdentifier("openSettings")
                } label: {
                    Image(systemName: "ellipsis").font(.title2)
                        .frame(width: 44, height: 44).background(OceanPalette.ink, in: Circle())
                }
                .foregroundStyle(.white).accessibilityLabel("Меню")
                .accessibilityIdentifier("surfaceMenu")
                 .accessibilityFocused($focusedControl, equals: "surfaceMenu")
            }
            Text("Курс на глубину")
                .font(.system(.largeTitle, design: .rounded).bold())
                .foregroundStyle(.white).accessibilityAddTraits(.isHeader)
                .frame(maxWidth: .infinity, alignment: .leading)
            Spacer(minLength: size.height * 0.22)
            VStack(alignment: .leading, spacing: 12) {
                Button { showingCampaign = true } label: {
                    HStack(spacing: 16) {
                        VStack(alignment: .leading, spacing: 6) {
                            Text("Экспедиция \(engine.mission?.number ?? 1) из 3")
                                .font(.subheadline).foregroundStyle(OceanPalette.teal)
                            Text(engine.mission?.title ?? "Затонувший «Астер»")
                                .font(.title2.bold()).foregroundStyle(.white)
                                .fixedSize(horizontal: false, vertical: true)
                        }
                        Spacer(minLength: 0)
                        Image(systemName: "chevron.right").foregroundStyle(.white)
                    }
                    .frame(maxWidth: .infinity, minHeight: 60, alignment: .leading)
                    .padding(18).background(OceanPalette.ink, in: RoundedRectangle(cornerRadius: 20))
                }
                .buttonStyle(.plain).disabled(!engine.isCampaign)
                .accessibilityIdentifier("openCampaign")
                .accessibilityHint("Выбрать другую экспедицию и прочитать задание")
                if let id = recovery.savedID {
                    Button { openReturnURL(ReturnRoute(id: id).url) } label: {
                        HStack { Spacer(); Text("Продолжить"); Spacer(); Image(systemName: "play.fill") }
                    }
                        .buttonStyle(DiveButtonStyle()).accessibilityIdentifier("continueExpedition")
                        .accessibilityHint("Восстанавливает незавершённую экспедицию на паузе")
                }
                Button {
                    showingMap = false
                    if recovery.savedID != nil { confirmNewGame = true } else { engine.startGame() }
                } label: {
                    HStack { Spacer(); Text("Начать"); Spacer(); Image(systemName: "arrow.right") }
                }
                .buttonStyle(DiveButtonStyle()).accessibilityLabel("Начать экспедицию")
                .accessibilityIdentifier("startDive").accessibilityFocused($focusedControl, equals: "startDive")
                Button("Как играть") { showingHelp = true }
                    .font(.body).foregroundStyle(.white)
                    .frame(maxWidth: .infinity, minHeight: 44).accessibilityIdentifier("openHelp")
            }
        }
        .padding(.horizontal, 24)
        .padding(.top, max(insets.top, 48) + 12)
        .padding(.bottom, max(insets.bottom, 20) + 12)
        .frame(minHeight: size.height)
        .background(LinearGradient(colors: [OceanPalette.ink, .clear, OceanPalette.ink],
                                   startPoint: .top, endPoint: .bottom))
    }

