                    Text("С VoiceOver используй действия на руле. Пошаговое управление включается в настройках.")
                }.font(.body).foregroundStyle(.white).padding(24)
            }
            .background(OceanPalette.ink).navigationTitle("Как играть")
            .toolbar {
